-- 022_recipe_instructions.sql
-- Instrucciones detalladas para el recetario de TrainerBoost
-- 200 recetas con pasos profesionales, tiempos exactos y consejos de chef

UPDATE recetas SET instrucciones = $ins$Paso 1: Retira la piel y espinas de 200g de merluza fresca con pinzas. Pica la carne finamente con cuchillo o en procesador pulsando 4 veces.
Paso 2: Mezcla con 1 huevo batido, 2 cdas de pan rallado, 1 diente de ajo picado fino y perejil. Sazona con sal y pimienta negra.
Paso 3: Con las manos húmedas forma albóndigas del tamaño de una nuez (unos 3 cm). Obtendrás unas 12 piezas.
Paso 4: Lleva 600ml de caldo de pescado a ebullición suave en una cazuela. Ajusta el fuego para que hierva sin borbotones.
Paso 5: Introduce las albóndigas con cuidado. Cuécelas 10 minutos. Están listas cuando flotan y no tienen rosado en el interior.
Paso 6: Sirve en cuencos con el caldo caliente y espolvorea perejil fresco picado.
Consejo: Un chorrito de zumo de limón en el caldo justo antes de servir realza el sabor del pescado sin añadir más sal.$ins$ WHERE id = 'ba88f0d0-bfa1-4e0a-b003-4c93937a56ba';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sumerge 500g de almejas en agua fría con sal abundante 30 minutos para que expulsen arena. Aclara y escurre.
Paso 2: Pica finamente 4 dientes de ajo y media cebolla. Calienta 3 cdas de AOVE en sartén amplia a fuego medio.
Paso 3: Sofríe ajo y cebolla 3 minutos removiendo hasta que estén translúcidos sin dorarse.
Paso 4: Sube el fuego a alto. Añade las almejas escurridas y 100ml de vino blanco seco. Cubre con tapa.
Paso 5: Cocina 3-4 minutos agitando la sartén dos veces. Desecha las almejas que no se hayan abierto.
Paso 6: Espolvorea perejil fresco picado y sirve inmediatamente con el jugo de cocción.
Consejo: No abras la tapa los primeros 3 minutos: el vapor acumulado es lo que abre las almejas de forma uniforme.$ins$ WHERE id = '22688c9f-e2cd-439b-bd08-ebebeccff959';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escurre bien 6 pimientos del piquillo de bote. Ábrelos por la mitad y colócalos en una fuente plana.
Paso 2: Lamina 1 diente de ajo muy fino y dispón las láminas sobre los pimientos.
Paso 3: Coloca 8 anchoas bien escurridas encima de los pimientos, una por cada pieza.
Paso 4: Pica un puñado de perejil fresco y espolvorea sobre el conjunto.
Paso 5: Riega con un hilo generoso de AOVE de calidad extra virgen. Sirve a temperatura ambiente.
Consejo: Si las anchoas son muy saladas, sumérgelas 5 minutos en leche fría: reduce el exceso de sal sin perder el sabor.$ins$ WHERE id = 'f846ccfd-4802-4603-acc9-cc71afcbc9e8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 2 cebollas en juliana fina (medias lunas de 3mm). Calienta 3 cdas de AOVE en sartén a fuego medio-bajo.
Paso 2: Pocha la cebolla 12-14 minutos removiendo cada 2 minutos hasta que esté muy blanda y ligeramente dorada.
Paso 3: Agrega 1 hoja de laurel, 1 cdta de pimentón dulce y 80ml de vino blanco. Sube el fuego y deja evaporar 2 minutos.
Paso 4: Corta 200g de atún fresco en dados de 3 cm. Sazona con sal y pimienta.
Paso 5: Incorpora el atún y cocina 3-4 minutos a fuego medio, girando los dados a mitad de tiempo. El interior debe quedar ligeramente rosado.
Paso 6: Retira el laurel y sirve el atún sobre la cama de cebolla.
Consejo: No sobrecocines el atún: en cuanto pierde el brillo crudo por fuera está en su punto. Pasarse 1 minuto lo seca completamente.$ins$ WHERE id = '4dcfdad2-9197-4803-8a51-bc3dc4e14fab';

UPDATE recetas SET instrucciones = $ins$Paso 1: Seca muy bien el bacalao desalado (200g) con papel de cocina por dentro y por fuera.
Paso 2: Calienta 150ml de AOVE a fuego muy bajo en cazuela de barro. Confita 4 dientes de ajo laminados y 1 guindilla 5 minutos sin que se doren. Retira y reserva.
Paso 3: Sube el fuego a medio-bajo. Introduce el bacalao con la piel hacia arriba y cocina 8 minutos.
Paso 4: Retira el bacalao. Con movimientos circulares constantes agita el aceite con la gelatina suelta durante 4-5 minutos hasta que emulsione y espese.
Paso 5: Vuelve a colocar el bacalao en la cazuela sobre la salsa cremosa blanca. Añade los ajos y guindilla por encima.
Paso 6: Sirve caliente directamente en la cazuela de barro.
Consejo: La emulsión del pil pil depende de la temperatura: el aceite no debe superar 70°C. Si se corta, añade una cda de agua fría y sigue moviendo.$ins$ WHERE id = '0906c70a-0352-4d60-8e74-d4ad3a95d3af';

UPDATE recetas SET instrucciones = $ins$Paso 1: Purga 500g de berberechos en agua salada fría 20 minutos. Aclara bajo el grifo.
Paso 2: Corta el brócoli en ramilletes medianos y la zanahoria en rodajas de 5mm. Pon agua a hervir en vaporera.
Paso 3: Coloca la zanahoria en el vapor primero. Cocina 4 minutos.
Paso 4: Añade el brócoli y los berberechos encima. Tapa y cocina 4-5 minutos más hasta que los berberechos se abran.
Paso 5: Descarta los berberechos que no se hayan abierto.
Paso 6: Sirve en plato hondo, exprime medio limón por encima y añade perejil fresco picado.
Consejo: Añadir una rodaja de jengibre al agua del vapor potencia el sabor del marisco sin taparlo.$ins$ WHERE id = 'c2a62540-8838-4b61-8aef-da78c02b83dd';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de pechuga en dados de 3 cm. Corta pimiento, cebolla y champiñones en trozos del mismo tamaño.
Paso 2: Marina el pollo 10 minutos con zumo de medio limón, 1 cda de AOVE, sal, pimienta, pimentón y orégano.
Paso 3: Si usas brochetas de madera, remójalas 10 minutos. Ensarta alternando pollo, pimiento, cebolla y champiñón.
Paso 4: Calienta la plancha a fuego fuerte. Pinta con unas gotas de AOVE.
Paso 5: Asa las brochetas 4-5 minutos por cada lado girando un cuarto de vuelta cada 2 minutos para dorado uniforme.
Paso 6: Comprueba que el pollo esté completamente blanco en el interior. Sirve inmediatamente.
Consejo: Marinar el pollo en la nevera 2 horas lo hace más tierno y sabroso. Si tienes tiempo, prepara el marinado la noche anterior.$ins$ WHERE id = 'be372d0c-18df-4781-bc04-587eff821029';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia 2 caballas, retira espinas centrales y córtalas en filetes. Sécalos con papel de cocina y sazóna.
Paso 2: Dora los filetes en 2 cdas de AOVE 2 minutos por cada lado a fuego medio-alto. Resérvalos en una fuente.
Paso 3: En la misma sartén sofríe 1 cebolla en juliana, 1 zanahoria en rodajas y 3 dientes de ajo enteros 8 minutos a fuego medio.
Paso 4: Agrega 2 hojas de laurel, pimienta negra en grano y 1 cdta de pimentón. Mezcla 30 segundos.
Paso 5: Vierte 100ml de vinagre de vino blanco y 80ml de AOVE. Lleva a ebullición y cuece 5 minutos.
Paso 6: Vierte el escabeche caliente sobre los filetes. Enfría y guarda en nevera al menos 2 horas antes de consumir.
Consejo: El escabeche mejora con el tiempo: preparado el día anterior el sabor es notablemente más profundo y equilibrado.$ins$ WHERE id = 'c62f95a2-cc6e-4cd1-aadc-a6c9603fe8e9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Corta 2 calabacines por la mitad a lo largo. Vacía el interior con cuchara dejando 1 cm. Reserva la pulpa.
Paso 2: Sofríe media cebolla picada en 1 cda de AOVE 5 minutos. Añade la pulpa del calabacín y cocina 3 minutos más.
Paso 3: Incorpora 200g de carne picada. Rompe con espátula y cocina 6 minutos a fuego medio-alto hasta que pierda el color rosado.
Paso 4: Agrega 2 cdas de tomate triturado, sal, pimienta y orégano. Mezcla y retira del fuego.
Paso 5: Rellena los botes de calabacín. Cúbrelos con queso rallado y coloca en bandeja de horno.
Paso 6: Hornea 18-20 minutos hasta que el calabacín esté tierno y el queso gratinado. Sirve inmediatamente.
Consejo: Espolvorea sal dentro del calabacín vaciado, déjalo 10 minutos boca abajo y sécalo: así no suelta agua durante el horneado.$ins$ WHERE id = '372478b0-8d1f-464d-a6c0-e35dd48bd6c8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Pela 400g de calabaza y córtala en dados de 2-3 cm uniformes.
Paso 2: Coloca en bandeja, riega con 1 cda de AOVE, sal y pimienta. Mezcla bien.
Paso 3: Hornea 20-22 minutos hasta que esté tierna al pincharla y con los bordes ligeramente caramelizados.
Paso 4: Desmiga 80g de queso feta en trozos irregulares. Prepara semillas de girasol y calabaza.
Paso 5: Esparce el feta sobre la calabaza caliente y vuelve a hornear 3 minutos para que temple el queso.
Paso 6: Sirve con hojas de rúcula fresca, las semillas y un hilo de miel.
Consejo: La combinación de miel y feta necesita contraste: una pizca de copos de chile o pimienta negra generosa equilibra el dulzor.$ins$ WHERE id = '2467fc2a-74d6-4521-9406-8fddf3e39131';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela y trocea groseramente 2 zanahorias, 2 tallos de apio, 1 puerro y un puñado de perejil con tallos.
Paso 2: Pon las verduras en olla grande con 1,5L de agua fría. Añade 1 rodaja de jengibre (1 cm) y 1 cdta de cúrcuma.
Paso 3: Lleva a ebullición a fuego fuerte. Baja a fuego medio-bajo y cocina 25 minutos sin tapar.
Paso 4: Retira con espumadera la espuma que suba a la superficie durante los primeros minutos.
Paso 5: Cuela el caldo por colador fino. Presiona las verduras con cuchara para extraer todo el líquido.
Paso 6: Sazona con sal marina y sirve en tazas. Añade unas gotas de limón al gusto.
Consejo: Añade la cúrcuma con un pellizco de pimienta negra: la piperina aumenta hasta 20 veces la absorción de la curcumina.$ins$ WHERE id = '1d923948-884e-46c9-8c2b-297d9b38360b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Divide 500g de coliflor en ramilletes. Pica 1 cebolla y 2 dientes de ajo.
Paso 2: Calienta 1 cda de AOVE en olla a fuego medio. Sofríe cebolla y ajo 4 minutos hasta que estén transparentes.
Paso 3: Añade 1 cdta de cúrcuma y remueve 30 segundos para que se tueste ligeramente.
Paso 4: Incorpora la coliflor y 600ml de caldo de verduras. Lleva a ebullición y cuece 12 minutos a fuego medio.
Paso 5: Tritura con batidora de mano hasta crema lisa. Añade 100ml de nata vegetal y tritura de nuevo.
Paso 6: Ajusta de sal. Sirve con un hilo de AOVE y semillas de sésamo negro.
Consejo: Para textura más sedosa, pasa la crema por colador fino tras triturar: elimina los últimos restos de coliflor.$ins$ WHERE id = '2c3ad71f-869c-410a-8104-166aacb0c13f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 500g de espárragos trigueros. Rompe cada uno por su punto natural de quiebre. Desecha los tallos duros.
Paso 2: Reserva 4-6 puntas para decorar. Trocea el resto en segmentos de 3 cm.
Paso 3: Sofríe media cebolla picada en 1 cda de AOVE 4 minutos. Añade los espárragos troceados y sofríe 3 minutos.
Paso 4: Vierte 500ml de caldo de verduras. Lleva a ebullición y cuece 8 minutos hasta que los espárragos estén muy tiernos.
Paso 5: Tritura. Añade 80ml de nata vegetal, sal y pimienta. Tritura hasta textura muy lisa.
Paso 6: Marca las puntas en plancha con gotas de AOVE durante 2 minutos. Decora la crema con ellas.
Consejo: Si te gusta el punto amargo del espárrago, no añadas la nata: la crema queda más intensa y con menos calorías.$ins$ WHERE id = 'fa29745f-463e-4c56-99c0-b1625f70b2d2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia 300g de puerros retirando hojas verdes exteriores. Córtalos en rodajas de 1 cm. Pela y corta 200g de patata en dados de 2 cm.
Paso 2: Funde 1 nuez de mantequilla con 1 cda de AOVE en olla a fuego medio. Sofríe el puerro 5 minutos hasta que esté blando.
Paso 3: Añade la patata y rehoga 2 minutos. Cubre con 700ml de caldo. Lleva a ebullición.
Paso 4: Baja a fuego medio y cuece 15 minutos hasta que la patata se deshaga con el tenedor.
Paso 5: Tritura. Añade 100ml de nata, sal y una pizca de nuez moscada. Tritura hasta textura cremosa.
Paso 6: Sirve con cebollino fresco picado por encima y un hilo de nata.
Consejo: Esta crema servida fría es la Vichyssoise francesa. Enfríala 2 horas en nevera: perfecta para el verano.$ins$ WHERE id = '363d0a86-f59f-4845-b6ec-d3c8f67107df';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 2 pepinos. Córtalos por la mitad a lo largo y retira las semillas con cuchara para evitar que la crema quede aguada.
Paso 2: Trocea los pepinos en dados gruesos. Pela 1 diente de ajo pequeño.
Paso 3: Pon en la batidora: pepinos, 200g de yogur griego, el ajo, zumo de medio limón, 8 hojas de menta fresca y media cdta de sal.
Paso 4: Tritura a máxima potencia 30-45 segundos hasta crema lisa y homogénea.
Paso 5: Prueba y ajusta sal o limón. Si queda muy espesa, añade 2 cdas de agua fría y tritura 10 segundos.
Consejo: Sirve muy fría directamente de la batidora o desde la nevera. Unas rodajas finas de pepino y hoja de menta la hacen elegante.$ins$ WHERE id = '83543d05-b3ae-4846-87f9-d577ecd0dae2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Prepara un trozo de papel de aluminio de 40x40 cm.
Paso 2: Corta en láminas finas medio calabacín, 1 tomate y medio pimiento. Coloca en el centro del papel.
Paso 3: Coloca 1 dorada limpia encima de las verduras. Sazona por dentro y por fuera.
Paso 4: Mete dentro del vientre 2 rodajas de limón, tomillo y romero. Riega con 2 cdas de AOVE.
Paso 5: Cierra el papillote doblando los bordes hacia arriba formando un paquete hermético.
Paso 6: Hornea 20-22 minutos. Abre con cuidado del vapor y sirve directamente del paquete.
Consejo: Nunca abras el papillote a mitad de cocción: perderías todo el vapor acumulado que es el que cocina el pescado.$ins$ WHERE id = 'ffb7c39d-ccbd-4840-9778-7cb13e3d1575';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca la mozzarella de la nevera 15 minutos antes para que esté a temperatura ambiente.
Paso 2: Corta 3 tomates maduros en rodajas de 1 cm. Corta 200g de mozzarella fresca en rodajas del mismo grosor.
Paso 3: Dispón en el plato intercalando rodajas de tomate y mozzarella ligeramente solapadas.
Paso 4: Coloca hojas de albahaca fresca encima sin picarlas para que conserven su aroma.
Paso 5: Sazona con sal marina en escamas y pimienta negra recién molida. Riega con un hilo generoso de AOVE de calidad.
Consejo: Esta ensalada solo funciona con tomates realmente maduros. Fuera de temporada usa tomates de colgar o pera, que tienen más sabor que los de invernadero.$ins$ WHERE id = 'fffe4f17-c9e8-4ce8-aef6-15b4b2f3b2b1';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 150g de langostinos cocidos o cuécelos 2 minutos en agua con sal. Escurre y reserva.
Paso 2: Corta 1 aguacate maduro en cubos de 2 cm. Riégalos con zumo de media lima para evitar oxidación.
Paso 3: Pica 1 tomate maduro en dados pequeños retirando las semillas.
Paso 4: Pica unas hojas de cilantro. Corta el jalapeño en rodajas finas sin semillas para picante suave.
Paso 5: Mezcla en bol: aguacate, tomate, langostinos, cilantro y jalapeño. Aliña con zumo del resto de lima, sal y 1 cdta de AOVE.
Paso 6: Sirve frío en copas o sobre lechuga.
Consejo: Para langostinos perfectamente tiernos, cuécelos solo hasta que cambien a rosado opaco. Un minuto más y quedan gomosos.$ins$ WHERE id = '3ab9f2a9-a30d-4f0d-9ede-6d42e7b3d8bc';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de col lombarda en juliana muy fina con cuchillo afilado o mandolina, descartando el tronco.
Paso 2: Pela y corta 1 manzana en bastones finos. Añade unas gotas de limón para que no se oxide.
Paso 3: Prepara la vinagreta: mezcla 1 cda de mostaza de Dijon, 2 cdas de vinagre de manzana, 3 cdas de AOVE, sal y pimienta.
Paso 4: Mezcla col, manzana, un puñado de pasas y nueces troceadas en bol grande.
Paso 5: Vierte la vinagreta y mezcla bien apretando ligeramente la col con las manos para que absorba el aliño.
Paso 6: Deja reposar 5 minutos antes de servir para que la col se ablande con el ácido.
Consejo: El vinagre de la vinagreta fija el color vibrante de la col lombarda además de ablandarla. Sin ácido, la col resulta dura y pierde su morado.$ins$ WHERE id = '255dc367-fffa-423d-869e-a7826674eff2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de col blanca en juliana muy fina descartando el tronco central duro.
Paso 2: Ralla 1 manzana verde Granny Smith con rallador grueso. Ralla también 1 zanahoria mediana pelada.
Paso 3: Prepara el aliño: mezcla 3 cdas de yogur natural, 1 cda de vinagre de manzana, sal y pimienta.
Paso 4: Combina en bol: col, manzana y zanahoria ralladas. Vierte el aliño y mezcla bien.
Paso 5: Prueba y ajusta acidez con más gotas de vinagre si es necesario.
Paso 6: Sirve frío. Añade semillas de sésamo tostadas por encima para textura crujiente.
Consejo: Rallar la manzana libera sus jugos, que se integran con el yogur y suavizan el sabor de la col mejor que si se cortara en dados.$ins$ WHERE id = '47dd41ae-c037-43c3-9af0-93140923f22d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de pasta integral en agua hirviendo con sal 10-12 minutos. Escurre y enfría bajo agua fría.
Paso 2: Escurre 150g de atún y desmiga con tenedor.
Paso 3: Trocea unas aceitunas negras, corta en tiras el pimiento asado y escurre 1 cda de alcaparras.
Paso 4: Mezcla la pasta fría con atún, aceitunas, pimiento y alcaparras en bol amplio.
Paso 5: Aliña con 2 cdas de AOVE, 1 cdta de vinagre de vino, sal y orégano seco.
Paso 6: Deja reposar 5 minutos tapado antes de servir para que los sabores se integren.
Consejo: Enfría la pasta bajo agua fría para detener la cocción, pero escúrrela muy bien: el aliño diluido en agua pierde toda su potencia.$ins$ WHERE id = 'dd03f6a0-0817-46dc-ab70-3532014c82bf';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 2 pepinos y córtalos en rodajas de 5mm. Espolvorea con sal y deja escurrir en colador 5 minutos.
Paso 2: Mezcla el aliño: 150g de yogur natural, 1 diente de ajo rallado fino, zumo de medio limón, sal y pimienta.
Paso 3: Pica finamente 8-10 hojas de menta fresca.
Paso 4: Seca el pepino con papel de cocina. Combina con el aliño de yogur y la menta.
Paso 5: Mezcla con suavidad. Sirve frío inmediatamente o refrigera hasta 1 hora.
Consejo: Esta ensalada es la base del Tzatziki griego. Sirviéndola como salsa con pan de pita acompaña perfectamente cualquier carne a la plancha.$ins$ WHERE id = 'bb80c48a-b88c-40ff-abc4-fc1662ba551c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Enjuaga 120g de quinoa bajo el grifo 1 minuto frotando con los dedos para eliminar la saponina amarga.
Paso 2: Cuece en 240ml de agua con sal: hierve, baja el fuego, tapa y cocina 12 minutos. Apaga y reposa 5 minutos tapada.
Paso 3: Pela 150g de gambas y sazona. Saltea en sartén con 1 cda de AOVE a fuego fuerte 2 minutos por lado. Reserva.
Paso 4: Corta medio pepino en cubos pequeños y 1 tomate en dados. Pica hojas de menta.
Paso 5: Extiende la quinoa para que se enfríe 3 minutos. Mezcla con pepino, tomate y menta.
Paso 6: Coloca las gambas encima. Aliña con zumo de 1 limón y un chorrito de AOVE.
Consejo: La quinoa está lista cuando aparece una pequeña espiral blanca en cada grano: es el germen separándose, señal de cocción perfecta.$ins$ WHERE id = '1f7a4f1e-9a29-487a-98d5-a1a3a0bf3db8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Usa remolacha cocida de bote. Córtala en dados de 2 cm o láminas finas.
Paso 2: Prepara la vinagreta: 1 cda de vinagre balsámico reducido, 2 cdas de AOVE, sal y pimienta. Emulsiona con tenedor.
Paso 3: Coloca una cama de rúcula fresca en el plato.
Paso 4: Distribuye la remolacha sobre la rúcula. Desmiga 80g de queso de cabra en trozos irregulares.
Paso 5: Esparce un puñado de nueces troceadas groseramente.
Paso 6: Vierte la vinagreta justo antes de servir y añade escamas de sal marina.
Consejo: La remolacha tiñe todo lo que toca. Vierte la vinagreta en el último momento para que los colores del plato se mantengan al presentarlo.$ins$ WHERE id = '37fda5d2-e9d5-46d5-b2f5-5d129a187a9d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 150g de lentejas pardinas en agua sin sal 15 minutos hasta que estén enteras pero tiernas. Escurre y sazona en caliente.
Paso 2: Corta 1 zanahoria en cubos pequeños y cuece al vapor 5 minutos.
Paso 3: Pica media cebolla morada fina y sumerge en agua fría 5 minutos para suavizar el sabor picante.
Paso 4: Trocea medio pepino en dados. Escurre la cebolla morada.
Paso 5: Mezcla en bol las lentejas tibias con zanahoria, pepino y cebolla. Aliña con 2 cdas de AOVE, 1 cdta de comino, zumo de medio limón, sal y pimienta.
Paso 6: Sirve templada con hojas de cilantro o perejil fresco.
Consejo: Sala las lentejas solo al final: añadirla durante la cocción endurece su piel y puede duplicar el tiempo de cocción.$ins$ WHERE id = '96bdbbcb-e1af-40b5-9070-6d9b655b0b65';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 150g de pechuga con sal, pimienta y AOVE. Calienta plancha a fuego fuerte.
Paso 2: Cocina la pechuga 5-6 minutos por el primer lado sin moverla.
Paso 3: Da la vuelta. Cocina 4-5 minutos más. Los jugos al pinchar deben ser claros y no rosados.
Paso 4: Deja reposar 3 minutos antes de cortar en tiras.
Paso 5: Prepara la base: lechuga, tomate en gajos, aguacate en láminas y pepino en rodajas. Elabora la vinagreta con AOVE, vinagre, sal y pimienta.
Paso 6: Coloca el pollo caliente sobre la ensalada fría y aliña en el momento de servir.
Consejo: El calor del pollo recién cocinado marchita ligeramente la lechuga en contacto. Sírvela siempre recién hecha para este efecto.$ins$ WHERE id = '1c4c5717-8b6f-4446-b3bd-8bd85bde4a2f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava y seca 200g de espinacas frescas. Colócalas en bol amplio.
Paso 2: Calienta 2 cdas de AOVE en sartén pequeña a fuego medio. Añade 1 diente de ajo laminado.
Paso 3: Cuando el ajo chisporrotee (30 segundos), añade 30g de piñones. Tuesta 2 minutos removiendo hasta que doren.
Paso 4: Agrega un puñado de pasas a la sartén y mezcla 30 segundos más.
Paso 5: Vierte el aceite caliente con piñones, pasas y ajo directamente sobre las espinacas. El aceite tibio las marchita ligeramente.
Paso 6: Sazona con sal, pimienta y unas gotas de vinagre de Jerez. Sirve inmediatamente.
Consejo: Vierte el aceite desde cierta altura para que llegue a todas las espinacas. No remuevas demasiado: deben quedar apenas marchitas, no cocinadas del todo.$ins$ WHERE id = 'bbe97905-4587-495c-a401-9431f6b12364';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 200g de mezclum en bol. Si está húmedo, seca bien con papel o centrifugadora.
Paso 2: Prepara la vinagreta: 3 cdas de AOVE, 1 cda de vinagre de vino blanco, sal y pimienta. Bate hasta emulsionar.
Paso 3: Tuesta en sartén seca a fuego medio las semillas de girasol y pipas de calabaza 2 minutos removiendo. Apaga cuando empiecen a saltar.
Paso 4: Vierte la vinagreta sobre los brotes y mezcla suavemente con las manos para no aplastar las hojas.
Paso 5: Añade semillas tostadas y sésamo crudo por encima. Sirve inmediatamente.
Consejo: Aliña siempre en el último momento: el ácido oxida y marchita los brotes en minutos. Si la preparas antes, guarda el aliño aparte.$ins$ WHERE id = '26c381d1-dc84-465e-8f43-d6f6fc4c9866';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 300g de gambas dejando el último segmento de la cola. Sécalas bien con papel de cocina.
Paso 2: Lamina 6 dientes de ajo muy finos. Corta media guindilla en rodajas sin semillas.
Paso 3: Calienta 5 cdas de AOVE en cazuelita a fuego medio. Añade ajo y guindilla.
Paso 4: Cuando el ajo empiece a coger color dorado claro (1-2 minutos), sube el fuego a fuerte.
Paso 5: Añade las gambas en una sola capa. Cocina 1-1,5 minutos por lado hasta que cambien a rosado opaco.
Paso 6: Retira del fuego, espolvorea perejil fresco picado y sirve inmediatamente chisporrotando.
Consejo: Las gambas se cocinan en segundos a fuego alto. Preferible que queden ligeramente menos hechas: el calor residual de la cazuela las termina en la mesa.$ins$ WHERE id = 'df21a7ac-a109-4748-bbcc-f03744d05965';

UPDATE recetas SET instrucciones = $ins$Paso 1: Retira la corteza de 400g de sandía sin semillas y trocea.
Paso 2: Pela 2 tomates maduros y trocéalos. Pela y desemilla medio pepino. Trocea medio pimiento.
Paso 3: Añade 1 diente de ajo pequeño, 2 cdas de AOVE, 1 cda de vinagre de vino blanco y media cdta de sal.
Paso 4: Tritura todo a máxima potencia 1 minuto hasta mezcla completamente lisa.
Paso 5: Pasa por colador fino para textura sedosa. Refrigera al menos 30 minutos.
Paso 6: Sirve muy frío en vasos. Decora con dados de sandía fresca y hojas de menta.
Consejo: Si el gazpacho queda muy líquido por la sandía, añade medio tomate más y vuelve a triturar. El frío potencia el equilibrio de sabores.$ins$ WHERE id = '5e0594d3-b273-4344-9e4f-60efa4b1870e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 1 perdiz troceada. Dórala en cazuela con AOVE a fuego fuerte 3 minutos por lado. Reserva.
Paso 2: En la misma cazuela sofríe 3 dientes de ajo enteros con romero y tomillo 2 minutos.
Paso 3: Añade 200g de hongos troceados y sofríe 5 minutos hasta que se doren.
Paso 4: Incorpora la perdiz y cubre con 600ml de agua o caldo de caza. Lleva a ebullición, baja el fuego y cuece 35 minutos tapado.
Paso 5: Saca la perdiz, deshuesa la carne y reincorpora al caldo. Añade las tortas sin levadura troceadas para espesar.
Paso 6: Cuece 5 minutos más a fuego bajo removiendo. Debe quedar espeso y contundente. Ajusta de sal y sirve muy caliente.
Consejo: El gazpacho manchego es un guiso de caza espesado con tortas de pan ácimo, un plato de pastores de La Mancha que nada tiene que ver con el gazpacho andaluz.$ins$ WHERE id = '483d9ee3-d9ae-4f9c-8a7e-9ab97b772964';

UPDATE recetas SET instrucciones = $ins$Paso 1: Seca bien 200g de filetes de lenguado con papel de cocina. Sazona con sal y pimienta por ambas caras.
Paso 2: Enharina ligeramente los filetes sacudiendo el exceso.
Paso 3: Funde 20g de mantequilla en sartén antiadherente a fuego medio-alto hasta que deje de espumar y dore ligeramente.
Paso 4: Coloca los filetes. Cocina 2-3 minutos sin moverlos. Da la vuelta con espátula plana.
Paso 5: Cocina 1-2 minutos más. El lenguado está listo cuando se deshace al presionarlo con el dedo.
Paso 6: Añade 1 cda de alcaparras y zumo de medio limón a la sartén. Mezcla 20 segundos y vierte sobre los filetes con perejil picado.
Consejo: La mantequilla noisette, cocinada hasta tomar color dorado y oler a nueces, es donde el lenguado queda espectacular.$ins$ WHERE id = '3c6a711e-ebae-4d75-a299-7b5c74a53db9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Coloca 200g de lomo de merluza en bandeja con papel de horno.
Paso 2: Lamina 2 dientes de ajo y dispón sobre el pescado. Exprime zumo de medio limón.
Paso 3: Añade alcaparras escurridas alrededor y espolvorea perejil fresco picado generosamente.
Paso 4: Riega con 2 cdas de AOVE. Coloca 2 rodajas de limón sobre el pescado.
Paso 5: Hornea 12-14 minutos hasta que la carne se separe en lascas al presionar con tenedor.
Paso 6: Sirve directamente de la bandeja para conservar todos los jugos de cocción.
Consejo: Presiona el centro del pescado con el dedo: debe ceder ligeramente pero no sentirse crudo. Si rebota como goma, está pasado.$ins$ WHERE id = 'df6cfca2-8f3c-4d3b-aa79-3e810d398bfb';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 400g de patatas y córtalas en dados de 3 cm. Sécalas muy bien con papel de cocina.
Paso 2: Calienta aceite abundante a 170°C. Fríe las patatas en dos tandas 6-7 minutos por tanda hasta que estén tiernas sin dorar. Escurre.
Paso 3: Sube el aceite a 190°C. Fríe de nuevo 2-3 minutos hasta que estén doradas y crujientes. Escurre y sala.
Paso 4: Para la salsa brava: sofríe media cebolla, 1 diente de ajo y guindilla 5 minutos. Añade pimentón picante y tomate frito. Tritura.
Paso 5: Para el alioli: maja 1 diente de ajo con sal, añade 3 cdas de mayonesa y 1 cdta de limón.
Paso 6: Sirve las patatas calientes con salsa brava y alioli.
Consejo: El doble frito es el secreto: la primera fritura cocina el interior, la segunda crea la costra crujiente. No te saltes ningún paso.$ins$ WHERE id = '37ea3ca6-9723-425f-b433-4c4933d6f7f0';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 100g de gambas crudas. Pica la mitad finamente para el relleno. Reserva el resto enteras.
Paso 2: Mezcla las gambas picadas con sal, pimienta y unas gotas de limón.
Paso 3: Coloca una cucharada de relleno en el extremo ancho de cada filete de lenguado (200g) y enrolla. Asegura con palillo si es necesario.
Paso 4: Dora los rollitos en 1 cda de mantequilla 2 minutos por lado a fuego medio. Retira y reserva.
Paso 5: En la misma sartén, sofríe media cebolla 3 minutos. Añade 60ml de vino blanco y deja evaporar. Incorpora 100ml de nata y las gambas enteras. Cocina 3 minutos.
Paso 6: Devuelve los rollitos a la sartén 2 minutos. Sirve con la salsa por encima.
Consejo: Coloca los rollitos con el cierre hacia abajo en la sartén: la presión y el calor los mantienen cerrados sin necesitar palillo.$ins$ WHERE id = 'f1572d46-165e-45a7-8556-0b95eaf58e01';

UPDATE recetas SET instrucciones = $ins$Paso 1: Aplana ligeramente 200g de pechuga con el puño para igualar el grosor y lograr cocción uniforme.
Paso 2: Mezcla 2 cdas de mostaza de Dijon con 1 diente de ajo rallado, tomillo seco y 1 cda de AOVE.
Paso 3: Unta la pechuga con la mostaza por ambas caras. Deja marinar 10 minutos.
Paso 4: Calienta sartén antiadherente a fuego medio-alto. Cocina la pechuga 5-6 minutos por el primer lado sin moverla.
Paso 5: Da la vuelta. Cocina 4-5 minutos más hasta que el interior esté blanco y los jugos al pinchar sean claros.
Paso 6: Deja reposar 3 minutos antes de cortar en diagonal. Sirve con el jugo de la sartén.
Consejo: La mostaza actúa como adobo y como sellante: forma una costra que mantiene la jugosidad de la pechuga durante la cocción.$ins$ WHERE id = '0b0a0c40-b076-4902-8bdd-421a6dfa1426';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Lava 4 pimientos medianos. Córtales la tapa y retira semillas y nervios blancos.
Paso 2: Escurre bien 200g de atún. Pica media cebolla muy fina. Escurre 1 cda de alcaparras.
Paso 3: Mezcla en bol: atún desmenuzado, 100g de queso crema, cebolla y alcaparras. Sazona con pimienta y unas gotas de limón.
Paso 4: Rellena los pimientos apretando bien para que no queden huecos. Coloca en bandeja de horno.
Paso 5: Hornea 20-22 minutos hasta que los pimientos estén tiernos y ligeramente arrugados.
Paso 6: Deja templar 5 minutos. Añade un hilo de AOVE y perejil picado.
Consejo: Para una versión más rápida, rellena pimientos del piquillo de bote en frío: la textura ya está cocida y solo necesitas el relleno recién hecho.$ins$ WHERE id = '7af19a52-7ed4-494d-9030-6b33274811da';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta en dados de 1,5 cm: 1 calabacín, 1 pimiento y 1 cebolla. Pela y pica 2 tomates maduros.
Paso 2: Calienta 3 cdas de AOVE en sartén amplia a fuego medio. Sofríe la cebolla 4 minutos.
Paso 3: Añade el pimiento y cocina 4 minutos. Incorpora el calabacín y 2 dientes de ajo picados. Sofríe 5 minutos removiendo ocasionalmente.
Paso 4: Agrega el tomate, sal, pimienta y una pizca de azúcar para contrarrestar la acidez. Cuece 8 minutos hasta que reduzca y espese.
Paso 5: Haz 2 huecos en el pisto con cuchara. Casca 1 huevo en cada hueco. Tapa la sartén.
Paso 6: Cocina a fuego bajo 3-4 minutos hasta que las claras estén cuajadas y las yemas aún líquidas.
Consejo: Para yemas cuajadas, añade 1 minuto más de cocción tapado. Para yemas líquidas, retira la sartén del fuego nada más cuajar las claras.$ins$ WHERE id = '2130378d-ca91-4770-b20e-70c84dbfcbc5';

UPDATE recetas SET instrucciones = $ins$Paso 1: Aplana 200g de pechuga. Sazona con sal, pimienta, zumo de limón, ajo rallado y tomillo. Deja marinar 5 minutos.
Paso 2: Separa el brócoli en ramilletes pequeños y corta la zanahoria en rodajas de 4mm.
Paso 3: Pon agua a hervir en vaporera. Coloca la zanahoria primero y cocina 3 minutos. Añade el brócoli y cocina 4 minutos más.
Paso 4: Calienta una plancha a fuego fuerte. Cocina la pechuga 4-5 minutos por cada lado.
Paso 5: La pechuga está lista cuando los jugos al pinchar son claros y la carne no tiene rosado.
Paso 6: Sirve la pechuga fileteada en diagonal sobre las verduras al vapor. Riega con AOVE y unas gotas de limón fresco.
Consejo: Las verduras al vapor conservan casi todos sus nutrientes. Para más sabor, añade una rodaja de limón al agua de la vaporera.$ins$ WHERE id = 'c83361d7-d6cf-42e5-a32d-c7420eb32e63';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 4 muslos de pollo. Dóralos en cazuela con AOVE a fuego fuerte 4 minutos por lado hasta que estén bien dorados. Reserva.
Paso 2: En la misma cazuela sofríe 2 dientes de ajo picados y media cebolla 5 minutos a fuego medio.
Paso 3: Tuesta 30g de almendras en sartén seca 2 minutos. Machaca en el mortero con 1 yema de huevo duro, azafrán y un chorrito de caldo.
Paso 4: Incorpora el majado al sofrito. Añade 200ml de caldo de pollo. Devuelve los muslos.
Paso 5: Tapa y cuece a fuego bajo 25 minutos girando los muslos a mitad de tiempo.
Paso 6: Pica la clara del huevo duro y espolvorea con perejil fresco. Sirve con pan o arroz.
Consejo: Disuelve el azafrán en una cda de caldo caliente antes de añadirlo: libera todo su color y aroma sin que queden hebras sueltas.$ins$ WHERE id = '81af34f5-87e1-44a6-a137-d5c075c76553';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de rape en medallones de 3-4 cm. Sazona con sal y pimienta.
Paso 2: Dora 2 rebanadas de pan en sartén con AOVE hasta que estén crujientes y doradas. Reserva.
Paso 3: En la misma sartén, fríe 3 dientes de ajo laminados hasta dorar. Añade 40g de almendras crudas y tuesta 2 minutos.
Paso 4: Tritura en mortero o batidora el pan, las almendras y el ajo con unas hebras de azafrán disuelto en 1 cda de caldo. Añade más caldo para obtener una salsa.
Paso 5: Lleva la salsa a sartén a fuego medio. Introduce los medallones y cocina 8-10 minutos girando una vez.
Paso 6: Espolvorea perejil fresco picado y sirve con abundante salsa.
Consejo: El rape admite bien la cocción prolongada sin deshacerse. Está hecho cuando el centro está firme pero cede ligeramente al presionar.$ins$ WHERE id = 'b7f6aea7-da49-4495-b438-47784d01c4e6';

UPDATE recetas SET instrucciones = $ins$Paso 1: Rompe 200g de espárragos por su punto natural de quiebre. Trocéalos en segmentos de 2-3 cm.
Paso 2: Calienta 1 cda de AOVE en sartén antiadherente a fuego medio. Añade 1 diente de ajo laminado.
Paso 3: Cuando el ajo empiece a dorar (1 minuto), añade los espárragos. Saltea 4-5 minutos hasta que estén tiernos con mordida.
Paso 4: Baja el fuego al mínimo. Bate 3 huevos con sal y pimienta y viértelos sobre los espárragos.
Paso 5: Con espátula de silicona, remueve lentamente haciendo movimientos de pliegue 2-3 minutos. Retira del fuego antes de que cuaje del todo.
Paso 6: El revuelto debe quedar cremoso y ligeramente líquido. Sirve inmediatamente.
Consejo: Retira la sartén del fuego cuando parece que faltan 30 segundos: el calor residual termina la cocción perfectamente.$ins$ WHERE id = '321bcc96-12e9-4400-9758-f44dd56bffcc';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca 180g de salmón de la nevera 10 minutos antes. Sécalo y sazona con sal y pimienta.
Paso 2: Calienta plancha a fuego alto hasta que esté muy caliente. Añade unas gotas de AOVE.
Paso 3: Coloca el salmón con la piel hacia abajo. Cocina 4 minutos sin moverlo para que la piel quede crujiente.
Paso 4: Da la vuelta. Cocina 2-3 minutos más. El interior debe quedar rosado pero no crudo.
Paso 5: En otra sartén con 1 cda de AOVE, sofríe 1 diente de ajo laminado 30 segundos. Añade 200g de espinacas frescas y saltea 2 minutos.
Paso 6: Sirve el salmón sobre las espinacas. Exprime limón fresco y añade un hilo de AOVE crudo.
Consejo: Presiona el centro del salmón con el dedo: si cede como gelatina, está en su punto jugoso. Si rebota firme, está pasado.$ins$ WHERE id = 'ceaf2231-801a-4110-9dc3-f07c593e5309';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia 300g de judías verdes retirando los hilos. Córtalas en trozos de 4-5 cm.
Paso 2: Pela y corta 200g de patatas en dados de 2 cm.
Paso 3: Cuece judías y patatas juntas en agua hirviendo con sal durante 12 minutos. Escurre y reserva.
Paso 4: Calienta 2 cdas de AOVE en sartén. Sofríe 2 dientes de ajo picados 1 minuto sin que se quemen.
Paso 5: Añade 1 tomate troceado, 1 cdta de pimentón dulce y sal. Sofríe 5 minutos hasta que el tomate reduzca.
Paso 6: Incorpora judías y patatas. Mezcla y cocina 2-3 minutos para que absorban el sofrito. Rectifica de sal.
Consejo: Añade el pimentón fuera del fuego o a fuego muy bajo: si se quema amarga y pierde el color rojo brillante.$ins$ WHERE id = '94ec0dca-8bf6-4f28-b8ed-8e75990f7a32';

UPDATE recetas SET instrucciones = $ins$Paso 1: Trocea 200g de pollo. Pela y corta en rodajas 1 zanahoria y 1 tallo de apio. Limpia el puerro y trocéalo.
Paso 2: Calienta 1 cda de AOVE en olla. Dora ligeramente el pollo 3 minutos.
Paso 3: Añade las verduras y 800ml de caldo de pollo. Lleva a ebullición.
Paso 4: Baja a fuego medio y cuece 20 minutos. Retira la espuma que suba a la superficie.
Paso 5: Añade 60g de fideos finos y cuece 3-4 minutos según el paquete.
Paso 6: Comprueba que el pollo esté completamente blanco. Rectifica de sal y sirve con perejil fresco.
Consejo: Introduce el pollo en el agua aún fría: la extracción de gelatina y sabores es mucho mayor que añadiéndolo al agua hirviendo.$ins$ WHERE id = 'de18e3ff-b383-4a0c-86ea-7e5c03d61dd3';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta en juliana fina (bastones de 3-4 cm y 3mm de grosor): zanahoria, puerro, pimiento y nabo.
Paso 2: Calienta 1 cda de AOVE en olla. Sofríe las verduras 3 minutos a fuego medio.
Paso 3: Vierte 800ml de caldo de verduras. Lleva a ebullición.
Paso 4: Añade 50g de fideos finos. Cuece según el paquete (3-5 minutos). Las verduras deben quedar tiernas pero no deshacerse.
Paso 5: Rectifica de sal. Si el caldo está soso, añade un chorrito de salsa de soja.
Paso 6: Sirve caliente con perejil fresco picado y un hilo de AOVE.
Consejo: Cortar las verduras en juliana uniforme garantiza que todas se cocinen al mismo tiempo y la textura sea consistente en cada cucharada.$ins$ WHERE id = 'a38edf67-368c-4ef0-b369-a7b97bbeaac9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pica 1 cebolla, 2 dientes de ajo, 1 zanahoria, 1 tallo de apio y 1 calabacín en dados de 1 cm.
Paso 2: Calienta 2 cdas de AOVE en olla grande. Sofríe cebolla, zanahoria y apio 5 minutos. Añade ajo 1 minuto más.
Paso 3: Añade 200ml de tomate triturado y las demás verduras. Sofríe 3 minutos.
Paso 4: Vierte 1L de caldo. Añade 1 lata de alubias blancas escurridas. Lleva a ebullición.
Paso 5: Incorpora 60g de pasta pequeña y cuece 10 minutos a fuego medio.
Paso 6: Ajusta de sal y pimienta. Sirve con parmesano rallado y un hilo de AOVE.
Consejo: El minestrone mejora de un día para otro. Guárdalo sin la pasta y añádela al recalentar para que no se pase.$ins$ WHERE id = '26cee0c6-c3ed-43cc-b595-12a1b5cce9be';

UPDATE recetas SET instrucciones = $ins$Paso 1: Seca 180g de salmón fresco con papel de cocina. Sazona con sal y pimienta por todos los lados.
Paso 2: Calienta sartén de hierro a fuego muy fuerte hasta que eche humo ligeramente.
Paso 3: Marca el salmón 45 segundos por cada uno de los 4 lados: debe quedar cocinado solo 2-3mm en el exterior, crudo en el centro.
Paso 4: Retira y enfría en nevera 2 minutos. Córtalo en lonchas de 1 cm con cuchillo afilado.
Paso 5: Hidrata el wakame en agua fría 5 minutos y escúrrelo. Corta el pepino en rodajas finas. Mezcla con sésamo tostado.
Paso 6: Sirve el salmón sobre la ensalada. Vierte la salsa de 2 cdas de soja, 1 de lima y 1 cdta de jengibre rallado.
Consejo: Para cortar el tataki limpiamente, usa un cuchillo seco y muy afilado con un movimiento de tracción largo, sin sierra.$ins$ WHERE id = '298c480c-cd04-4bfa-8b31-c11dfd7bd399';

UPDATE recetas SET instrucciones = $ins$Paso 1: Desmiga 100g de bacalao desalado con los dedos en trozos pequeños, comprobando que no hay espinas.
Paso 2: Usa pimiento rojo asado o de bote. Córtalo en tiras finas. Lamina 1 diente de ajo.
Paso 3: Calienta 1 cda de AOVE en sartén de 20 cm. Sofríe el ajo 30 segundos. Añade el bacalao y el pimiento. Saltea 2 minutos.
Paso 4: Bate 3 huevos con poca sal (el bacalao ya sala) y pimienta. Vierte sobre el bacalao y pimiento.
Paso 5: Cuece a fuego medio-bajo 3 minutos hasta que los bordes cuajen. Con plato encima, da la vuelta y cocina 2 minutos más.
Paso 6: Sirve caliente o templada cortada en cuartos.
Consejo: Comprueba que el bacalao esté bien desalado sumergiéndolo en agua 24h antes y cambiando el agua 3 veces.$ins$ WHERE id = '182c45cc-5066-4574-91c6-94cb10473869';

UPDATE recetas SET instrucciones = $ins$Paso 1: Ralla o corta en cubos muy pequeños medio calabacín, medio pimiento y media cebolla.
Paso 2: Calienta 1 cda de AOVE en sartén de 20 cm a fuego medio. Sofríe las verduras con 1 diente de ajo picado 5 minutos.
Paso 3: Bate 3 huevos con sal y pimienta.
Paso 4: Vierte los huevos sobre las verduras sofritas. Mueve la sartén en círculos para que el huevo se distribuya.
Paso 5: Cocina a fuego bajo 3-4 minutos hasta que los bordes estén cuajados y el centro aún esté ligeramente líquido.
Paso 6: Cubre con un plato y da la vuelta con confianza. Cocina 1-2 minutos más. Sirve templada.
Consejo: Retira la sartén del fuego cuando el interior aún parece algo húmedo: el calor residual cuaja el centro perfectamente.$ins$ WHERE id = '7667ba5e-3081-4fc6-9934-b32984d989c6';

UPDATE recetas SET instrucciones = $ins$Paso 1: Mezcla 300g de carne picada mixta con 1 huevo, 2 cdas de pan rallado, 1 diente de ajo picado fino, perejil y sal. Amasa 1 minuto.
Paso 2: Con las manos húmedas forma albóndigas de 3 cm. Enharína ligeramente y sacude el exceso.
Paso 3: Calienta 2 cdas de AOVE en cazuela. Dora las albóndigas a fuego medio-alto 2 minutos por lado hasta que estén doradas por fuera. Reserva.
Paso 4: En la misma cazuela sofríe 1 cebolla picada y 2 dientes de ajo 5 minutos. Añade 400g de tomate triturado, sal, pimienta y una pizca de azúcar.
Paso 5: Devuelve las albóndigas a la salsa. Tapa y cuece a fuego bajo 20 minutos. La salsa debe espesar.
Paso 6: Sirve con perejil fresco picado. Acompaña con arroz blanco o pan crujiente.
Consejo: No aplastes las albóndigas al dorarlas: la costra que se forma sella los jugos. Déjalas que suelten solas cuando estén listas.$ins$ WHERE id = '883612ba-919b-4ebc-80db-0c2cf91a12d5';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Seca 400g de alitas con papel de cocina. Colócalas en bandeja con papel de horno.
Paso 2: Mezcla la marinada: salsa BBQ, 2 dientes de ajo rallados, 1 cdta de pimentón ahumado, 1 cdta de miel y 1 cda de AOVE.
Paso 3: Cubre las alitas con la marinada por todos los lados. Deja reposar 10 minutos.
Paso 4: Hornea 20 minutos. Saca y pinta de nuevo con más marinada.
Paso 5: Vuelve a hornear 15-20 minutos hasta que estén bien doradas, crujientes y los jugos sean claros al pinchar.
Paso 6: Deja reposar 5 minutos antes de servir. La piel debe estar caramelizada y brillante.
Consejo: Para alitas extra crujientes, dóralas 3 minutos bajo el grill del horno al final de la cocción. Vigila de cerca que no se quemen.$ins$ WHERE id = 'b1fa04d2-c71c-4a5d-9f0e-a5accc67f59e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Remoja 200g de alubias blancas desde la noche anterior. Escurre y enjuaga.
Paso 2: Cubre las alubias con agua fría en olla. Lleva a ebullición, retira la espuma y cuece 30 minutos hasta que estén tiernas. Escurre reservando el caldo.
Paso 3: Pica 1 puerro, 1 zanahoria y 1 tallo de apio en dados de 1 cm. Sofríe con 2 cdas de AOVE en olla grande 5 minutos.
Paso 4: Añade 2 dientes de ajo picados, 1 hoja de laurel y sofríe 2 minutos más.
Paso 5: Incorpora las alubias cocidas y el caldo reservado hasta cubrir. Cuece 10 minutos a fuego medio.
Paso 6: Ajusta de sal y pimienta. Retira el laurel y sirve caliente con un hilo de AOVE.
Consejo: Si usas alubias de bote ya cocidas, reduce el tiempo de cocción total a 20 minutos y añade el caldo del bote para más sabor.$ins$ WHERE id = '22649ef0-39f6-4206-a25e-38ef36cce5f1';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de arroz blanco o integral (tiempo según tipo). Escurre y reserva.
Paso 2: Corta pimiento, brócoli en ramilletes pequeños y zanahoria en rodajas finas.
Paso 3: Calienta el wok o sartén grande a fuego muy fuerte hasta que humee. Añade 2 cdas de aceite de sésamo o girasol.
Paso 4: Saltea las verduras más duras primero (zanahoria) 2 minutos. Añade brócoli y pimiento. Saltea 2 minutos más removiendo constantemente.
Paso 5: Incorpora el arroz cocido. Añade 2 cdas de salsa de soja, 1 cdta de jengibre rallado y sésamo. Saltea 1-2 minutos.
Paso 6: Prueba de sal. Sirve inmediatamente con semillas de sésamo por encima.
Consejo: El secreto del wok es el fuego muy alto y no dejar de mover. Las verduras deben quedar al dente y con color vivo, no blandas ni apagadas.$ins$ WHERE id = '2bcae240-06c0-4a92-85d6-a4322e0e4546';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de arroz integral en 400ml de agua con sal a fuego medio. Cuando hierva, baja el fuego, tapa y cuece 25 minutos. Reposa 5 minutos.
Paso 2: Separa el brócoli en ramilletes y corta la zanahoria en rodajas de 4mm. Cuece al vapor 5 minutos.
Paso 3: Escurre 150g de atún al natural y desmiga.
Paso 4: Mezcla en bol el arroz tibio con las verduras al vapor.
Paso 5: Añade el atún, sal, pimienta y 2 cdas de AOVE. Mezcla con suavidad.
Paso 6: Sirve tibio o a temperatura ambiente. Puedes añadir unas gotas de salsa de soja o zumo de limón.
Consejo: El arroz integral necesita el doble de tiempo que el blanco pero aporta el triple de fibra. Cocínalo en mayor cantidad y congela porciones para ahorrar tiempo.$ins$ WHERE id = '7763c2e8-de44-4341-b337-82046ec8576d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 1 calabacín, 1 pimiento, 1 tomate y 1 cebolla en dados de 2 cm. Sofríe en 2 cdas de AOVE 10 minutos a fuego medio.
Paso 2: Sazona el sofrito con sal, pimienta y pimentón dulce.
Paso 3: Seca 180g de bacalao desalado con papel de cocina. Sazona ligeramente.
Paso 4: Dora el bacalao en sartén aparte con 1 cda de AOVE 3 minutos por lado a fuego medio-alto.
Paso 5: Coloca el bacalao sobre el pisto de verduras. Tapa y cuece a fuego bajo 5 minutos para que los sabores se integren.
Paso 6: Sirve con perejil fresco picado y un hilo de AOVE crudo.
Consejo: Dorando el bacalao por separado antes de añadirlo al pisto se forma una costra que evita que se deshaga durante la cocción final.$ins$ WHERE id = '4d20701a-28db-4796-9586-5810f3a99936';

UPDATE recetas SET instrucciones = $ins$Paso 1: Purga 500g de berberechos en agua salada 20 minutos. Aclara y escurre.
Paso 2: Calienta una olla amplia a fuego fuerte. Añade los berberechos, el zumo de 1 limón, 2 dientes de ajo picados y 60ml de vino blanco.
Paso 3: Tapa y cocina 3-4 minutos agitando la olla cada minuto.
Paso 4: Descarta los berberechos que no se hayan abierto.
Paso 5: Sirve en bol hondo con el jugo de cocción.
Paso 6: Espolvorea perejil fresco picado y acompaña con pan para mojar en el jugo.
Consejo: El jugo que sueltan los berberechos es uno de los caldos más sabrosos del mar. Pan crujiente para aprovechar hasta la última gota.$ins$ WHERE id = 'd87f3c74-cb34-4b78-bf5e-bb47a9af64e7';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Corta 2 berenjenas en rodajas de 1 cm. Espolvorea con sal y deja escurrir 10 minutos. Sécalas con papel.
Paso 2: Asa las rodajas de berenjena en sartén con AOVE 2 minutos por lado o pincélalas con AOVE y hornea 15 minutos.
Paso 3: Prepara la salsa de tomate: sofríe 1 diente de ajo en AOVE, añade 400g de tomate triturado, sal, pimienta y albahaca. Cuece 10 minutos.
Paso 4: En una fuente de horno monta capas: salsa de tomate, berenjena, mozzarella en rodajas y parmesano rallado. Repite.
Paso 5: Termina con salsa, mozzarella y abundante parmesano.
Paso 6: Hornea 20 minutos hasta que el queso esté gratinado y burbujee. Deja reposar 5 minutos antes de servir.
Consejo: Salando la berenjena antes de cocinarla extraes la humedad y el amargor. No te saltes este paso o la parmesana quedará aguada.$ins$ WHERE id = '697a47bb-9633-411a-9504-a704e2dbf97f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 100g de arroz integral (o basmati) según instrucciones. Escurre y reserva.
Paso 2: Corta 150g de tempeh en dados de 2 cm. Marina 10 minutos en 2 cdas de soja, 1 cdta de aceite de sésamo y 1 cdta de sirope de agave.
Paso 3: Dora el tempeh marinado en sartén con 1 cda de aceite a fuego medio-alto 3-4 minutos por lado hasta que esté dorado.
Paso 4: Corta aguacate en láminas, col morada en juliana fina y descongela o hierve 5 minutos el edamame.
Paso 5: Monta el bowl: base de arroz, tempeh dorado, aguacate, col morada y edamame en secciones.
Paso 6: Aliña con sésamo tostado y un hilo de salsa de soja o tahini.
Consejo: El tempeh absorbe mejor el marinado si lo cortas y lo dejas en remojo 30 minutos en la nevera. Cuanto más tiempo, más sabor.$ins$ WHERE id = '47b0fe31-021f-4918-b5f5-e63e47fcaee6';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 100g de arroz blanco según instrucciones. Escurre y reserva.
Paso 2: Sazona 150g de pechuga de pollo en dados con sal y pimienta. Dora en sartén con 1 cda de AOVE a fuego fuerte 5 minutos. Reserva.
Paso 3: Hierve o descongela 100g de edamame 3 minutos. Escurre.
Paso 4: Corta 1 aguacate en láminas y riégalo con unas gotas de lima.
Paso 5: Monta el bowl en secciones: arroz, pollo dorado, edamame y aguacate.
Paso 6: Aliña con 2 cdas de salsa de soja, 1 cdta de aceite de sésamo y semillas de sésamo tostado.
Consejo: Cortar el pollo en dados antes de cocinarlo en lugar de hacerlo entero reduce el tiempo de cocción a la mitad y garantiza que cada trozo quede bien dorado.$ins$ WHERE id = 'c19625c0-875e-483f-b9ce-5eb741fa77c2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Enjuaga 180g de quinoa. Cuece en 360ml de agua con sal: hierve, baja el fuego, tapa y cuece 12 minutos. Reposa 5 minutos tapada.
Paso 2: Sazona 150g de pechuga y cocina a la plancha 5 minutos por lado. Deja reposar 3 minutos y corta en tiras.
Paso 3: Corta 1 aguacate en cubos y rocía con unas gotas de limón. Parte los tomates cherry por la mitad. Corta el pepino en rodajas.
Paso 4: Extiende la quinoa en el bowl como base.
Paso 5: Coloca el pollo, aguacate, tomates cherry y pepino en secciones.
Paso 6: Aliña con zumo de 1 limón, 2 cdas de AOVE, sal y pimienta. Añade hojas de cilantro o perejil.
Consejo: Disponer los ingredientes del bowl en secciones separadas no es solo estético: permite al comensal mezclar al gusto en cada cucharada.$ins$ WHERE id = '441db279-c19b-4ccb-8d61-339e5d84c633';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lleva 1L de caldo de hueso ya preparado a ebullición en olla mediana.
Paso 2: Pela y corta 1 zanahoria en rodajas de 4mm. Corta 1 tallo de apio en trozos.
Paso 3: Añade la zanahoria y el apio al caldo hirviendo. Cuece 5 minutos.
Paso 4: Incorpora 80g de fideos finos. Cuece 3-4 minutos según el paquete.
Paso 5: Rectifica de sal. El caldo de hueso ya tiene sabor intenso, prueba antes de añadir sal.
Paso 6: Sirve en cuencos hondos con perejil fresco picado.
Consejo: El caldo de hueso tiene alto contenido en colágeno y gelatina. Si está bien hecho, al enfriarse se solidifica. Eso es señal de calidad.$ins$ WHERE id = '74d70e49-1595-4c10-81b3-ce41c69b6e3c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon en olla grande: medio pollo troceado, 1 zanahoria, 1 tallo de apio y 1 puerro en trozos. Cubre con 1,5L de agua fría.
Paso 2: Lleva a ebullición y retira la espuma con espumadera. Añade sal.
Paso 3: Baja a fuego medio-bajo y cuece 30 minutos. El pollo debe estar completamente tierno.
Paso 4: Saca el pollo, deshuesa y desmenuza. Cuela el caldo.
Paso 5: Devuelve el caldo a la olla. Añade 80g de arroz y la carne deshuesada. Cuece 15 minutos más.
Paso 6: Ajusta de sal y sirve con perejil fresco picado.
Consejo: Arrancar el caldo desde agua fría es el método clásico para extraer toda la gelatina y los sabores del pollo en profundidad.$ins$ WHERE id = '261b5946-331b-44d9-8817-a7e3c6ded41f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Cuece 8 láminas de canelones en agua con sal según indicaciones. Extiende sobre un trapo húmedo.
Paso 2: Sofríe 1 cebolla y 1 diente de ajo picados en AOVE 5 minutos. Añade 200g de carne picada y cocina 8 minutos. Agrega 3 cdas de tomate frito, sal y nuez moscada.
Paso 3: Prepara la bechamel: derrite 30g de mantequilla, añade 30g de harina y remueve 1 minuto. Agrega 400ml de leche caliente poco a poco removiendo hasta que espese. Sazona.
Paso 4: Rellena cada lámina con la carne. Enrolla y coloca en fuente engrasada con tomate frito.
Paso 5: Cubre con bechamel y espolvorea parmesano rallado.
Paso 6: Hornea 25 minutos hasta que el queso esté gratinado y dorado. Deja reposar 5 minutos.
Consejo: La bechamel no debe tener grumos: si los tiene, pásala por el colador o tritura con batidora de mano antes de cubrir los canelones.$ins$ WHERE id = '83fb4f08-e3ee-45dc-adb3-1ef6fdf35365';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de corvina fresca en cubos de 2 cm. Es fundamental que el pescado sea muy fresco.
Paso 2: Exprime el zumo de 3 limones y 1 lima. Vierte sobre el pescado para que quede completamente sumergido.
Paso 3: Deja macerar en nevera 15 minutos. El ácido cocinará el exterior del pescado sin calor.
Paso 4: Pica muy fina media cebolla morada. Sumerge en agua fría 5 minutos para suavizar el picante.
Paso 5: Escurre la cebolla. Mezcla con el pescado marinado, cilantro fresco picado y ají o guindilla al gusto.
Paso 6: Prueba de sal. Sirve inmediatamente en vasos o copas con leche de tigre (el zumo de maceración).
Consejo: El ceviche no se puede guardar: el ácido sigue cocinando el pescado y endurece la textura. Prepara y sirve siempre en el momento.$ins$ WHERE id = '38d09c7e-79bc-48eb-aa07-92b277568e98';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 160°C. Sazona el codillo con sal y pimienta. Dóralo en cazuela con AOVE a fuego fuerte 3-4 minutos por lado.
Paso 2: Retira el codillo. Sofríe en la misma cazuela 1 cebolla en cuartos y 3 dientes de ajo 3 minutos.
Paso 3: Añade 300g de chucrut, 2 hojas de laurel, bayas de enebro y 200ml de cerveza.
Paso 4: Devuelve el codillo. El líquido debe llegar a un tercio del codillo. Tapa la cazuela.
Paso 5: Hornea tapado 2 horas. A mitad de tiempo, gira el codillo y comprueba el líquido, añade un poco de agua si es necesario.
Paso 6: El codillo está listo cuando la carne se separa del hueso al tocarlo. Sirve con la guarnición de chucrut.
Consejo: Para una piel más crujiente, sube el horno a 220°C los últimos 15 minutos y destapa la cazuela. Vigila para que no se queme.$ins$ WHERE id = '93d2e9d0-d7eb-4ba5-8c9b-12d4ddf6d569';

UPDATE recetas SET instrucciones = $ins$Paso 1: Trocea 300g de cordero en piezas de 4-5 cm. Sazona con sal y pimienta. Dora en cazuela con AOVE a fuego fuerte 3 minutos por lado.
Paso 2: Reserva el cordero. En la misma cazuela sofríe 1 cebolla, 1 pimiento rojo y 2 dientes de ajo picados 8 minutos.
Paso 3: Añade 2 tomates troceados y sofríe 5 minutos hasta que reduzcan.
Paso 4: Devuelve el cordero. Añade 100ml de vino blanco. Deja evaporar el alcohol 2 minutos.
Paso 5: Tapa y cuece a fuego bajo 45 minutos hasta que el cordero esté muy tierno. Si queda muy líquido, destapa los últimos 10 minutos.
Paso 6: Rectifica de sal. Sirve con arroz blanco o patatas cocidas.
Consejo: El chilindrón es una salsa de pimiento y tomate típica de Aragón. Puede hacerse también con pollo o conejo usando los mismos tiempos.$ins$ WHERE id = 'c3d38243-b49f-470c-92e5-5dddc2a5666b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Divide 500g de brócoli en ramilletes. Pica 1 cebolla y 2 dientes de ajo.
Paso 2: Calienta 1 cda de AOVE en olla a fuego medio. Sofríe cebolla y ajo 4 minutos.
Paso 3: Añade el brócoli y cubre con 600ml de caldo de verduras. Lleva a ebullición y cuece 10 minutos.
Paso 4: Tritura con batidora de mano hasta textura lisa. Añade 50g de queso cheddar rallado y 100ml de nata.
Paso 5: Tritura de nuevo hasta que el queso se integre completamente. Sazona con sal, pimienta y nuez moscada.
Paso 6: Sirve caliente con un poco más de queso rallado por encima.
Consejo: Para una crema más ligera, usa nata de avena en lugar de nata animal: el resultado es igual de cremoso con menos grasa saturada.$ins$ WHERE id = '30447cdd-710d-4fa4-86b1-dc306cfef086';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela y corta 500g de calabaza en dados de 2 cm. Pica 1 cebolla y 2 dientes de ajo.
Paso 2: Calienta 1 cda de AOVE en olla. Sofríe cebolla, ajo y 1 cdta de jengibre rallado 4 minutos.
Paso 3: Añade 1 cdta de curry y mezcla 30 segundos. Incorpora la calabaza y rehoga 2 minutos.
Paso 4: Vierte 200ml de leche de coco y 200ml de caldo de verduras. Lleva a ebullición y cuece 18 minutos.
Paso 5: Tritura hasta textura muy lisa. Ajusta de sal y consistencia añadiendo más caldo si es necesario.
Paso 6: Sirve con un hilo de leche de coco en espiral y pipas de calabaza tostadas.
Consejo: La leche de coco entera da más cremosidad que la light. Si quieres reducir calorías, usa la light solo en el acabado final del plato.$ins$ WHERE id = 'b3a3e425-c293-4ffa-b9c6-612c999bdfe5';

UPDATE recetas SET instrucciones = $ins$Paso 1: Enjuaga 200g de lentejas rojas. Pica 1 cebolla, 2 dientes de ajo y prepara las especias: 1 cdta de cúrcuma y 1 cdta de comino.
Paso 2: Sofríe cebolla y ajo en 1 cda de AOVE 4 minutos. Añade las especias y mezcla 30 segundos.
Paso 3: Incorpora las lentejas y cubre con 600ml de agua o caldo. Lleva a ebullición.
Paso 4: Cuece a fuego medio 15 minutos. Las lentejas rojas se deshacen solas y espesan el caldo.
Paso 5: Añade 100ml de leche de coco. Tritura parcialmente con batidora de mano para una textura semi-cremosa.
Paso 6: Ajusta de sal. Sirve con un hilo de AOVE y cilantro fresco si tienes.
Consejo: Las lentejas rojas no necesitan remojo previo y se cocinan en 15 minutos, lo que las convierte en la legumbre más rápida de preparar.$ins$ WHERE id = '6f6f4874-e75a-4b0f-bb0d-58293a3dcc20';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 500g de zanahorias y córtalas en rodajas. Pica 1 cebolla y 1 trozo de jengibre fresco de 2 cm.
Paso 2: Sofríe cebolla y jengibre en 1 cda de AOVE 4 minutos. Añade 1 cdta de curry y mezcla 30 segundos.
Paso 3: Añade la zanahoria y cubre con 600ml de caldo de verduras. Lleva a ebullición y cuece 18 minutos.
Paso 4: Tritura hasta textura completamente lisa. Añade 100ml de leche de coco.
Paso 5: Tritura de nuevo y ajusta de sal y pimienta.
Paso 6: Sirve con un hilo de leche de coco y semillas de cilantro o un pellizco de curry por encima.
Consejo: El jengibre fresco tiene el doble de potencia que el seco. Si no tienes fresco, usa media cdta de jengibre en polvo.$ins$ WHERE id = 'af79b750-9599-423b-98a7-3056faec7867';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Extiende 2kg de sal gruesa en una capa de 1 cm en una bandeja. Coloca la dorada limpia encima.
Paso 2: Introduce dentro del vientre del pescado 2 rodajas de limón, 1 rama de tomillo y 1 rama de romero.
Paso 3: Cubre completamente la dorada con el resto de la sal. La sal debe formar un montículo compacto que tape todo el pescado.
Paso 4: Hornea 25 minutos. La sal formará una costra dura y blanca.
Paso 5: Saca del horno y golpea la costra de sal con el mango de un cuchillo para romperla. Retira la sal con cuidado.
Paso 6: Pela la piel con cuidado y sirve los filetes directamente. El pescado queda perfectamente jugoso.
Consejo: La dorada a la sal no queda salada: la costra actúa como un horno dentro del horno que cocina al vapor sellando todos los jugos.$ins$ WHERE id = 'fea661d2-7709-4579-8818-00e3d10fbe26';

UPDATE recetas SET instrucciones = $ins$Paso 1: Hidrata 100g de algas variadas (wakame, agar-agar, kombu) en agua fría 5-10 minutos según instrucciones. Escurre y trocéalas si son muy largas.
Paso 2: Pela 1 pepino y córtalo en rodajas muy finas con mandolina o cuchillo afilado.
Paso 3: Prepara el aliño asiático: 2 cdas de soja baja en sal, 1 cda de vinagre de arroz, 1 cdta de aceite de sésamo y 1 cdta de jengibre rallado.
Paso 4: Mezcla las algas escurridas con el pepino en un bol.
Paso 5: Vierte el aliño y mezcla bien. Deja reposar 2 minutos para que los sabores se integren.
Paso 6: Sirve con sésamo tostado por encima.
Consejo: Las algas se rehidratan mucho: 10g de algas secas se convierten en 80-100g hidratadas. Calcula siempre en seco para no pasarte de cantidad.$ins$ WHERE id = '00a47055-e38b-4c11-b34c-34b5e378eddc';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 2 huevos en agua hirviendo exactamente 10 minutos para que la yema quede bien cuajada. Enfría en agua con hielo y pela.
Paso 2: Limpia y lamina 150g de champiñones. Corta 2 lonchas de bacon en tiras.
Paso 3: Dora el bacon en sartén seca a fuego medio-alto 3 minutos hasta que esté crujiente. Añade los champiñones y saltea 3 minutos más.
Paso 4: Prepara la vinagreta de mostaza: 2 cdas de AOVE, 1 cda de vinagre de vino, 1 cdta de mostaza, sal y pimienta.
Paso 5: Coloca 150g de espinacas frescas en un bol. Añade bacon y champiñones calientes. Parte los huevos en cuartos.
Paso 6: Vierte la vinagreta y coloca los huevos. Sirve inmediatamente.
Consejo: El bacon y los champiñones calientes marchitan ligeramente las espinacas al contacto, creando una textura perfecta entre crudo y cocinado.$ins$ WHERE id = '32c32b7b-423f-4a79-8a9d-41fe63a27583';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escurre 200g de garbanzos de bote y aclara con agua fría.
Paso 2: Pica 1 tomate en dados pequeños, medio pepino en cubos y media cebolla morada muy fina.
Paso 3: Sumerge la cebolla en agua fría 5 minutos para suavizar el sabor picante. Escurre.
Paso 4: Desmiga 80g de queso feta en trozos irregulares.
Paso 5: Mezcla en bol: garbanzos, tomate, pepino, cebolla y feta. Añade hojas de menta fresca picada.
Paso 6: Aliña con 2 cdas de AOVE, zumo de medio limón, sal y pimienta. Mezcla con suavidad para no desmenuzar el feta.
Consejo: Esta ensalada aguanta bien en nevera 24 horas. Guarda la menta y el aliño aparte y añádelos justo antes de servir.$ins$ WHERE id = '538dcf48-c8b8-4798-936f-be90faa082a3';

UPDATE recetas SET instrucciones = $ins$Paso 1: Hierve 200g de habas frescas o descongeladas 3 minutos. Escurre y pela la piel exterior de cada haba si son grandes (la piel interior es amarga).
Paso 2: Pica media cebolla morada muy fina. Sumerge 5 minutos en agua fría.
Paso 3: Desmiga 50g de queso feta en trozos.
Paso 4: Pica un puñado de menta fresca.
Paso 5: Mezcla en bol: habas, cebolla escurrida, feta y menta. Aliña con zumo de medio limón, 2 cdas de AOVE, sal y pimienta.
Paso 6: Sirve a temperatura ambiente o ligeramente templada.
Consejo: Pelar la piel exterior de las habas grandes (la segunda piel) elimina el amargor y les da una textura mucho más suave y cremosa.$ins$ WHERE id = '33a4e86e-f23e-41e1-a8e9-b5ecadfd7b2e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de pasta en agua hirviendo con sal según el paquete. Escurre reservando 2 cdas del agua de cocción.
Paso 2: Escurre 150g de atún al natural y desmiga con tenedor.
Paso 3: Mezcla la pasta escurrida con 2 cdas de pesto genovés. Añade las 2 cdas del agua de cocción para aflojar la salsa.
Paso 4: Parte los tomates cherry por la mitad.
Paso 5: Incorpora el atún desmenuzado y los tomates cherry. Mezcla con suavidad.
Paso 6: Sirve con rúcula fresca por encima y parmesano rallado. Puede tomarse caliente o a temperatura ambiente.
Consejo: El agua de cocción de la pasta tiene almidón que ayuda al pesto a adherirse mejor a la pasta. Nunca tires esa agua sin antes reservar un poco.$ins$ WHERE id = '5ef98097-c415-46e1-ba72-ba0f04615eea';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 150g de pechuga en tiras y dora en sartén con 1 cda de AOVE 5 minutos a fuego fuerte. Reserva.
Paso 2: Pela 1 mango maduro y córtalo en dados de 2 cm.
Paso 3: Prepara la vinagreta: 2 cdas de AOVE, 1 cda de vinagre de vino blanco o de manzana, sal y pimienta.
Paso 4: Coloca una cama de lechuga y rúcula mezcladas en el plato.
Paso 5: Añade el pollo tibio, los dados de mango y un puñado de nueces troceadas.
Paso 6: Vierte la vinagreta y sirve inmediatamente mientras el pollo aún está caliente.
Consejo: El mango debe estar maduro pero no blando: al presionarlo con el dedo debe ceder ligeramente sin hundirse. Un mango duro no tiene sabor.$ins$ WHERE id = '1069e076-a245-4c69-80f2-128e4e3db7fb';

UPDATE recetas SET instrucciones = $ins$Paso 1: Coloca 100g de rúcula fresca en una fuente amplia.
Paso 2: Pela 1 pera madura y córtala en láminas finas.
Paso 3: Usa un pelador de verduras para hacer virutas grandes de parmesano (60g). El pelador da láminas más elegantes que el rallador.
Paso 4: Trocea groseramente un puñado de nueces.
Paso 5: Prepara la vinagreta de módena: 1 cda de vinagre balsámico reducido, 2 cdas de AOVE, sal y pimienta.
Paso 6: Monta la ensalada con rúcula, pera, parmesano y nueces. Vierte la vinagreta y sirve inmediatamente.
Consejo: El vinagre balsámico reducido tiene más sabor y consistencia que el líquido. Si tienes el normal, hiérvelo 5 minutos a fuego bajo hasta que reduzca a la mitad.$ins$ WHERE id = '5124debc-1bb8-40cf-a4a2-57cbf51a918d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 2 huevos 10 minutos en agua hirviendo. Enfría en agua con hielo. Cuece 100g de judías verdes en agua hirviendo con sal 5 minutos. Enfría en agua con hielo.
Paso 2: Trocea 150g de atún en aceite y escurre. Prepara aceitunas negras y tomates cherry partidos.
Paso 3: Coloca en fuente plana: lechuga, judías verdes, tomates cherry y aceitunas.
Paso 4: Parte los huevos en cuartos y colócalos encima. Añade el atún y unas anchoas si tienes.
Paso 5: Prepara la vinagreta: 3 cdas de AOVE, 1 cda de vinagre de vino, 1 cdta de mostaza, sal y pimienta.
Paso 6: Vierte la vinagreta en el momento de servir sin remover demasiado para que los ingredientes mantengan su posición.
Consejo: La ensalada niçoise auténtica no lleva ni judías ni patata cocida, pero la adaptación española con ambas está perfectamente extendida y resulta más nutritiva.$ins$ WHERE id = '85211024-8623-47df-8767-5bf67249c7a2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Enjuaga 150g de quinoa. Cuece en 300ml de agua con sal 12 minutos. Reposa 5 minutos tapada.
Paso 2: Asa 6-8 espárragos en plancha con 1 cdta de AOVE 3-4 minutos. Córtalos en trozos de 3 cm.
Paso 3: Parte los tomates cherry por la mitad. Deshuesa unas aceitunas y pica hojas de menta.
Paso 4: Coloca la quinoa aún tibia en un bol amplio.
Paso 5: Mezcla con espárragos, tomates cherry, aceitunas y menta. Desmiga 80g de queso feta por encima.
Paso 6: Aliña con 2 cdas de AOVE, zumo de medio limón, sal y pimienta.
Consejo: La quinoa templada (no caliente ni fría) absorbe mejor el aliño. Prepara el aliño mientras la quinoa reposa y mézclalos en ese punto.$ins$ WHERE id = 'd843f7bf-e147-4f80-b95f-dcb82b564b5f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de espaguetis en agua hirviendo con sal según el paquete. Guarda 3 cdas del agua de cocción antes de escurrir.
Paso 2: Pela 200g de gambas crudas. Lamina 4 dientes de ajo. Corta media guindilla sin semillas.
Paso 3: Calienta 4 cdas de AOVE en sartén amplia a fuego medio. Dora el ajo y la guindilla 1 minuto.
Paso 4: Sube el fuego a fuerte. Añade las gambas y cocina 1,5 minutos por lado hasta que estén rosadas.
Paso 5: Incorpora los espaguetis escurridos y el agua de cocción reservada. Saltea 1 minuto mezclando bien.
Paso 6: Espolvorea perejil fresco picado abundante. Rectifica de sal y sirve inmediatamente.
Consejo: Las gambas se terminan cocinando con el calor residual cuando se mezclan con la pasta. Sácalas de la sartén siempre ligeramente menos hechas de lo que quieres en el plato.$ins$ WHERE id = '480451c5-8211-4093-8031-c1f49b22c5f0';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia y corta en dados 150g de sepia. Lamina 2 dientes de ajo y ralla 1 tomate maduro.
Paso 2: Calienta 3 cdas de AOVE en paella o sartén amplia. Dora el ajo, añade la sepia y saltea 5 minutos a fuego fuerte.
Paso 3: Añade el tomate rallado y sofríe 3 minutos. Agrega 180g de fideos de calibre medio y tuesta removiendo 2 minutos.
Paso 4: Infusiona unas hebras de azafrán en 1 cda de caldo caliente y vierte junto con 400ml de caldo de pescado caliente.
Paso 5: Cuece sin remover a fuego medio 10-12 minutos hasta que los fideos absorban el caldo. El fondo debe quedar ligeramente dorado.
Paso 6: Retira del fuego, tapa con trapo 2 minutos y sirve con alioli al lado.
Consejo: Para la fideuà auténtica, los fideos deben quedar en pie y ligeramente crujientes en las puntas superiores. No los remuevas una vez añadido el caldo.$ins$ WHERE id = '45522129-9cde-4195-a2a0-ac270c6985f6';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escurre 200g de garbanzos de bote y aclara con agua fría.
Paso 2: Calienta 2 cdas de AOVE en sartén a fuego medio. Sofríe 2 dientes de ajo picados 1 minuto.
Paso 3: Añade 1 cdta de pimentón dulce y media de comino. Remueve 20 segundos sin dejar que el pimentón se queme.
Paso 4: Incorpora los garbanzos y mezcla bien. Saltea 3 minutos a fuego medio-alto.
Paso 5: Añade 200g de espinacas frescas. Remueve hasta que se reduzcan completamente (2-3 minutos).
Paso 6: Sazona con sal, pimienta y un chorrito de limón. Sirve caliente.
Consejo: Este plato mejora con reposo. Preparado el día anterior los garbanzos absorben las especias y el resultado es notablemente más sabroso.$ins$ WHERE id = '6dfc53e8-e57c-4b25-8b4c-bff866403e1f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escalda y pela 500g de tomates maduros. Trocéalos. Pela y trocea medio pepino, medio pimiento verde y 1 diente de ajo.
Paso 2: Remoja 1 rebanada de pan del día anterior en agua 2 minutos. Escurre y exprímela bien.
Paso 3: Coloca en la batidora: tomates, pepino, pimiento, ajo, el pan escurrido, 3 cdas de AOVE, 1 cda de vinagre de Jerez y 1 cdta de sal.
Paso 4: Tritura a máxima potencia 2 minutos hasta que quede completamente liso.
Paso 5: Pasa por colador fino si quieres textura perfectamente sedosa. Enfría en nevera al menos 2 horas.
Paso 6: Sirve muy frío con guarnición: pepino en dados, pimiento en cubos y pan en trozos pequeños.
Consejo: El pan es el secreto de la textura cremosa del gazpacho: sin él queda líquido. Pero añade poco a poco hasta conseguir la consistencia que te gusta.$ins$ WHERE id = '020047cc-fd05-49f1-91c0-bedfb977c415';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 200g de lentejas en agua sin sal 20 minutos hasta que estén tiernas. Escurre y deja enfriar un poco.
Paso 2: Sofríe 1 cebolla y 2 dientes de ajo picados en AOVE 5 minutos. Deja enfriar.
Paso 3: Mezcla en bol: lentejas escurridas, sofrito frío, 40g de copos de avena, 1 cdta de comino, 1 cdta de pimentón, sal y pimienta.
Paso 4: Aplasta parcialmente con tenedor para que la mezcla se una. Forma 4 hamburguesas compactas.
Paso 5: Refrigera 15 minutos para que cojan consistencia. Dora en sartén con 1 cda de AOVE 4 minutos por lado.
Paso 6: Sirve en pan integral con lechuga, tomate y una salsa de yogur con comino.
Consejo: Si la mezcla queda muy blanda para formar las hamburguesas, añade 1 cda más de avena. Si queda muy seca, añade 1 cda de agua o zumo de limón.$ins$ WHERE id = 'a8aa8dcf-6665-4835-8678-48a9667b4a65';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia 300g de judías verdes, retira los extremos e hilos. Córtalas en trozos de 4 cm.
Paso 2: Cuece en agua hirviendo con sal 6-7 minutos hasta que estén tiernas con un poco de mordida. Escurre.
Paso 3: Calienta 1 cda de AOVE en sartén a fuego medio. Añade 2 dientes de ajo laminados y dora 1 minuto.
Paso 4: Añade 80g de jamón serrano en tiras o taquitos y saltea 2 minutos.
Paso 5: Incorpora las judías escurridas y mezcla bien 1-2 minutos para que absorban el sabor del jamón.
Paso 6: Rectifica de sal (el jamón ya sala bastante). Sirve caliente.
Consejo: Para judías con más color y textura más viva, sumérgelas en agua helada nada más escurrirlas: detiene la cocción y fija el color verde brillante.$ins$ WHERE id = 'feebf91d-4971-41d7-958e-b447d5cde3cd';

UPDATE recetas SET instrucciones = $ins$Paso 1: Mezcla 200g de pavo picado con 1 diente de ajo rallado, media cebolla rallada, comino, pimentón, sal y pimienta. Amasa bien.
Paso 2: Forma 2 cilindros compactos de unos 12 cm. Si tienes brochetas, ensártalos en ellas.
Paso 3: Cocina en plancha o sartén caliente con unas gotas de AOVE 3-4 minutos por cada lado (4 lados en total si es cilíndrico).
Paso 4: Mientras se cocina, prepara la salsa: mezcla yogur natural con pepino rallado, sal, ajo en polvo y eneldo.
Paso 5: Calienta el pan pita en la plancha 1 minuto por cada lado.
Paso 6: Sirve el kebab en el pan pita con la salsa de yogur, lechuga y rodajas de tomate.
Consejo: Para que los kebabs no se rompan en la plancha, asegúrate de que la mezcla esté bien amasada y los cilindros sean compactos. El truco es presionar bien al formarlos.$ins$ WHERE id = '68c4e40f-79ea-40d3-bf5a-be4ad5731632';

UPDATE recetas SET instrucciones = $ins$Paso 1: Remoja 200g de lentejas pardinas en agua fría 30 minutos. Escurre.
Paso 2: Calienta 2 cdas de AOVE en cazuela. Sofríe 1 cebolla, 1 pimiento verde y 2 dientes de ajo picados 6 minutos.
Paso 3: Añade 1 chorizo en rodajas y sofríe 3 minutos hasta que libere su grasa.
Paso 4: Incorpora 1 cdta de pimentón dulce y 1 hoja de laurel. Añade las lentejas y cubre con 600ml de agua. Lleva a ebullición.
Paso 5: Baja el fuego y cuece 25 minutos sin remover. El caldo debe reducir y espesar.
Paso 6: Retira el laurel. Ajusta de sal (el chorizo ya aporta). Sirve caliente con pan de hogaza.
Consejo: Las lentejas pardinas aguantan bien la cocción sin deshacerse. Si usas lentejas rojas o naranjas, el tiempo baja a 15 minutos pero quedará más cremoso.$ins$ WHERE id = '7811771e-b660-4aa1-b6d9-bd5c9bedfccb';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Coloca 200g de lubina en bandeja con papel de horno.
Paso 2: Lamina 2 dientes de ajo y dispón sobre el pescado. Añade alcaparras escurridas alrededor.
Paso 3: Exprime el zumo de 1 limón por encima. Añade 2 ramitas de tomillo fresco.
Paso 4: Riega con 2 cdas de AOVE y sazona con sal y pimienta.
Paso 5: Hornea 15-18 minutos según el grosor del filete. La carne debe separarse en lascas al presionar.
Paso 6: Sirve directamente de la bandeja con el jugo de cocción y unas rodajas de limón fresco.
Consejo: La lubina y la dorada son intercambiables en la mayoría de recetas. Elige siempre el pescado más fresco disponible ese día en la pescadería.$ins$ WHERE id = 'ddca5eb9-8c11-4966-8deb-a764708fcba6';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de macarrones en agua hirviendo con sal hasta que estén al dente. Escurre reservando 2 cdas del agua de cocción.
Paso 2: En la misma olla funde 1 cda de mantequilla a fuego medio. Añade 100g de pavo troceado en dados pequeños y dora 4 minutos.
Paso 3: Agrega 150ml de leche y el agua de cocción reservada. Calienta hasta que hierva suavemente.
Paso 4: Añade 50g de queso rallado (cheddar o gouda). Remueve hasta que se funda completamente.
Paso 5: Incorpora los macarrones escurridos. Mezcla bien para que la salsa cubra toda la pasta.
Paso 6: Sazona con sal, pimienta y una pizca de nuez moscada. Sirve inmediatamente.
Consejo: Si la salsa de queso queda muy espesa, añade un chorrito más de leche caliente. Si queda líquida, cuece 1-2 minutos más a fuego bajo removiendo.$ins$ WHERE id = '06257480-935a-4fbb-97f5-eed9116a548c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon agua a hervir en vaporera o olla con cesto. Prepara el caldo con las especias.
Paso 2: Corta 200g de merluza en trozos grandes. Separa el brócoli en ramilletes y la zanahoria en rodajas de 4mm.
Paso 3: Coloca la zanahoria en el vapor y cocina 3 minutos. Añade el brócoli y la merluza encima.
Paso 4: Cocina 5-6 minutos más hasta que el pescado esté opaco y se deshaga al tocarlo.
Paso 5: Prepara el aliño: zumo de 1 limón, 2 cdas de AOVE, eneldo fresco picado, sal y pimienta.
Paso 6: Sirve el pescado sobre las verduras y vierte el aliño caliente por encima.
Consejo: La merluza al vapor es el método de cocción que mejor conserva su sabor delicado. Añadir eneldo al agua del vapor aromatiza el pescado desde dentro.$ins$ WHERE id = '10207b06-fe4e-4b5f-9d34-b239e00622b4';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escurre bien 150g de atún al natural. Bate con 100g de queso crema hasta obtener una mezcla lisa y homogénea.
Paso 2: Añade zumo de medio limón, sal y pimienta negra. Mezcla. Si queda muy espeso, añade 1 cdta de AOVE.
Paso 3: Traslada la mousse a una manga pastelera o bolsa con la esquina cortada para servir.
Paso 4: Corta pepino en bastones de 7-8 cm, zanahoria en bastones similares y tallos de apio.
Paso 5: Sirve la mousse en un bol central con los palitos de verdura alrededor formando un ramo.
Consejo: Para una mousse más ligera, sustituye la mitad del queso crema por yogur griego 0%. El resultado es igual de cremoso con muchos menos calorías.$ins$ WHERE id = 'a76f9f9f-0e62-4f8a-b724-c06346b66886';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 190°C. Marina 4 muslos de pollo en el zumo de 1 limón, tomillo, 3 dientes de ajo machacados y AOVE durante 10 minutos.
Paso 2: Coloca los muslos marinados en bandeja de horno con la piel hacia arriba.
Paso 3: Hornea 30 minutos a 190°C.
Paso 4: Riega con los jugos de la bandeja, sube a 200°C y hornea 15-20 minutos más hasta que la piel esté dorada y crujiente.
Paso 5: Los muslos están listos cuando los jugos al pinchar el interior son completamente claros sin rastro de rosa.
Paso 6: Deja reposar 5 minutos. Desglasa la bandeja con un chorrito de caldo o vino y vierte sobre los muslos.
Consejo: Poner el pollo con la piel hacia arriba desde el principio es fundamental para que la piel quede crujiente. Si la cubres de líquido se vuelve blanda.$ins$ WHERE id = 'b4822683-778b-4c0b-9dad-255dbc2e5902';

UPDATE recetas SET instrucciones = $ins$Paso 1: Remoja 180g de fideos de arroz en agua caliente 5 minutos hasta que estén flexibles. Escurre.
Paso 2: Pela 150g de gambas. Bate 1 huevo. Prepara el resto de ingredientes: brotes de soja, cacahuetes troceados.
Paso 3: Calienta el wok a fuego muy fuerte con 2 cdas de aceite. Saltea las gambas 2 minutos. Apártalas a un lado.
Paso 4: Añade el huevo al lado libre del wok y revuelve rápidamente hasta que cuaje en trozos. Mezcla con las gambas.
Paso 5: Incorpora los fideos escurridos. Añade 2 cdas de salsa de soja, 1 de zumo de lima y 1 de azúcar moreno. Saltea 2 minutos.
Paso 6: Sirve con brotes de soja crudos, cacahuetes troceados, lima en cuartos y cebollino picado.
Consejo: El wok debe estar extremadamente caliente antes de añadir los ingredientes. Si el aceite no humea, el pad thai no tendrá el sabor ahumado característico.$ins$ WHERE id = 'e76cbb36-b658-4207-92f3-a8109435f6a8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sofríe pimiento verde, judías verdes troceadas y alcachofas en 3 cdas de AOVE en paella 5 minutos a fuego fuerte.
Paso 2: Ralla 2 tomates maduros y agrega a la paella. Sofríe 3 minutos.
Paso 3: Añade 200g de arroz bomba y nacara 2 minutos removiendo para que absorba el sofrito.
Paso 4: Infusiona azafrán en 1 cda de caldo caliente. Vierte junto con 500ml de caldo de verduras caliente. Sazona.
Paso 5: Cuece sin remover a fuego medio 8 minutos. Baja el fuego y cuece 10 minutos más. El caldo debe absorberse.
Paso 6: Sube el fuego los últimos 2 minutos para formar el socarrat (costra dorada del fondo). Reposa 5 minutos tapada.
Consejo: Una paella nunca se remueve después de añadir el caldo: mover el arroz libera almidón y lo vuelve cremoso como un risotto en lugar de quedarse suelto.$ins$ WHERE id = '9c8eda54-3453-4120-98a8-1a2884245d9c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 180g de pasta en agua hirviendo con sal hasta que esté al dente. Guarda 3 cdas del agua de cocción.
Paso 2: Parte 200g de tomates cherry por la mitad.
Paso 3: Mezcla en bol grande la pasta recién escurrida con 3 cdas de pesto. Añade el agua de cocción para que la salsa sea más fluida.
Paso 4: Incorpora los tomates cherry y mezcla con suavidad.
Paso 5: Distribuye en platos. Añade piñones tostados por encima.
Paso 6: Termina con parmesano recién rallado y una hoja de albahaca fresca.
Consejo: El pesto casero es superior al de bote, pero si usas bote, añade unas hojas de albahaca fresca y un chorrito de AOVE al momento de servir para potenciar el aroma.$ins$ WHERE id = 'e805a682-4fa6-47cf-9412-3e56fd810c47';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sofríe 1 cebolla y 2 dientes de ajo picados en 1 cda de AOVE 5 minutos.
Paso 2: Añade 150g de pavo picado. Rompe con espátula y cocina 6-7 minutos a fuego medio-alto.
Paso 3: Agrega 300ml de tomate triturado, sal, pimienta y una pizca de orégano. Cuece 15 minutos a fuego bajo hasta que espese.
Paso 4: Cuece 180g de pasta integral según el paquete (normalmente 10-12 min). Escurre.
Paso 5: Mezcla la pasta con la salsa boloñesa. Si está muy espesa, añade un chorrito del agua de cocción.
Paso 6: Sirve con parmesano rallado y albahaca fresca.
Consejo: La pasta integral absorbe más la salsa que la pasta blanca. Si dejas reposar 2 minutos antes de servir, la salsa se integra mucho mejor.$ins$ WHERE id = '179d09ac-0db2-4754-9f5c-bd6a55470a3c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 200g de pechuga en filetes y dora en sartén con 1 cda de AOVE 4 minutos por lado. Reserva y cubre con papel de aluminio.
Paso 2: En la misma sartén, añade 1 cda de mantequilla y lamina 200g de champiñones. Saltea 5 minutos a fuego fuerte hasta que se evapore el agua.
Paso 3: Añade 1 diente de ajo picado y sofríe 1 minuto.
Paso 4: Vierte 50ml de caldo de pollo y 150ml de nata. Lleva a ebullición a fuego medio.
Paso 5: Cuece la salsa 5 minutos removiendo hasta que espese. Sazona con sal, pimienta y perejil picado.
Paso 6: Sirve la pechuga fileteada con la salsa de champiñones por encima.
Consejo: El secreto de los champiñones salteados perfectos: sartén muy caliente, poco aceite y no remover los primeros 2 minutos. Así se doran en lugar de cocerse en su agua.$ins$ WHERE id = '4821812f-3a36-4013-aa06-83abc3efb15e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 200g de boniato y córtalo en trozos. Cuece en agua hirviendo con sal 15 minutos hasta que esté muy tierno.
Paso 2: Escurre y aplasta con tenedor o pasa por el pasapurés. Añade 1 cda de mantequilla y 50ml de leche caliente. Mezcla hasta obtener un puré liso. Sazona.
Paso 3: Sazona 200g de pechuga de pavo con sal, pimienta y romero.
Paso 4: Dora la pechuga en sartén con 1 cda de AOVE 5 minutos por lado a fuego medio.
Paso 5: Comprueba que la pechuga esté completamente cocinada sin rosado interior.
Paso 6: Sirve la pechuga sobre el puré de boniato. Espolvorea romero fresco picado.
Consejo: El boniato tiene un índice glucémico más bajo que la patata y más betacaroteno. Su dulzor natural hace que el puré no necesite azúcar ni mucha sal.$ins$ WHERE id = '5818d787-73ed-4eda-95ce-add32c2ffa68';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta en dados de 1 cm: 1 calabacín, 1 pimiento, 1 berenjena y 1 cebolla. Pica 3 tomates maduros.
Paso 2: Calienta 3 cdas de AOVE en sartén amplia. Sofríe la cebolla y el pimiento 5 minutos.
Paso 3: Añade la berenjena y el calabacín con 2 dientes de ajo picados. Sofríe 6 minutos más.
Paso 4: Incorpora los tomates, sal, pimienta y una pizca de azúcar. Cuece 10 minutos a fuego medio hasta que espese.
Paso 5: Sube el fuego a fuerte. Calienta 2 cdas de aceite en sartén aparte y fríe 2 huevos hasta que la yema esté cuajada pero brillante.
Paso 6: Sirve el pisto en un plato y coloca un huevo frito encima de cada ración.
Consejo: El pisto extremeño admite cualquier combinación de verduras de temporada. En verano, con pimientos asados del horno, es absolutamente excepcional.$ins$ WHERE id = '527a4a31-edeb-45b7-85e6-59bf1adedb77';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 150g de arroz para sushi en 300ml de agua: hierve, tapa y cuece 12 minutos a fuego bajo. Apaga y reposa 10 minutos.
Paso 2: Mezcla el arroz con 1 cda de vinagre de arroz, media cdta de azúcar y media cdta de sal. Extiende para que enfríe.
Paso 3: Corta 150g de atún fresco de calidad sushi en láminas finas de 3mm.
Paso 4: Corta 1 aguacate en láminas. Descongela o hierve el edamame 3 minutos.
Paso 5: Monta el bowl: base de arroz de sushi, atún en láminas, aguacate, edamame.
Paso 6: Aliña con salsa de soja, un hilo de aceite de sésamo y semillas de sésamo tostado.
Consejo: El atún para poke debe ser de calidad sashimi (fresco de primera) o haber sido congelado a -20°C al menos 48h para eliminar posibles parásitos.$ins$ WHERE id = '1d2d8d35-0b80-4899-8830-6dd1714eacc5';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 200g de pechuga de pollo. Cocina a la plancha 5-6 minutos por lado a fuego fuerte. Deja reposar 3 minutos y filetea.
Paso 2: Prepara la salsa César: mezcla 3 cdas de mayonesa, 1 diente de ajo rallado, 1 cdta de mostaza, zumo de medio limón y 2 cdas de parmesano rallado.
Paso 3: Tuesta 2 rebanadas de pan integral en dados en sartén con unas gotas de AOVE hasta que estén doradas y crujientes.
Paso 4: Coloca lechuga romana troceada en un bol. Añade la salsa César y mezcla bien.
Paso 5: Distribuye el pollo fileteado encima de la lechuga.
Paso 6: Añade los picatostes de pan, parmesano rallado y pimienta negra recién molida.
Consejo: La salsa César casera sin anchoas pierde algo de sabor umami. Para compensarlo, añade 1 cdta de salsa Worcestershire a la mezcla.$ins$ WHERE id = '93466b96-6e35-4bf5-bbd2-fa659afd0923';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de pechuga de pollo en tiras de 2-3 cm.
Paso 2: Calienta 1 cda de aceite en wok o sartén a fuego fuerte. Saltea el pollo 4 minutos hasta que esté dorado. Reserva.
Paso 3: En la misma sartén añade 2 cdas de pasta de curry rojo. Sofríe 1 minuto removiendo.
Paso 4: Vierte 200ml de leche de coco. Lleva a ebullición y cuece 3 minutos.
Paso 5: Devuelve el pollo. Añade 1 pimiento en tiras y unas hojas de lima kaffir si tienes. Cuece 5 minutos a fuego medio.
Paso 6: Rectifica de sal. Sirve sobre arroz jazmín con cebollino y lima en cuartos.
Consejo: La pasta de curry rojo varía mucho de picante según la marca. Prueba siempre antes de añadir la cantidad completa para ajustar al nivel de picante que prefieres.$ins$ WHERE id = '4d8b86d5-8bd7-485e-82bc-feb74c7947f8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Frota medio pollo con sal, pimienta, AOVE y el zumo de 1 limón por dentro y por fuera.
Paso 2: Introduce dentro del pollo la cáscara del limón exprimido, una cabeza de ajo cortada por la mitad y ramitas de tomillo y romero.
Paso 3: Coloca el pollo en bandeja con la pechuga hacia arriba. Añade unos dientes de ajo sueltos alrededor.
Paso 4: Hornea 50 minutos. A los 25 minutos rega el pollo con sus propios jugos.
Paso 5: Para comprobar que está listo, pincha el muslo: los jugos deben salir completamente claros sin rastro de rosa.
Paso 6: Deja reposar 10 minutos antes de trinchar para que los jugos se redistribuyan. Sirve con los jugos de la bandeja.
Consejo: El reposo después del asado es tan importante como la cocción: sin él, todos los jugos se escapan al trinchar y el pollo queda seco.$ins$ WHERE id = '7d53bccb-7309-44d9-9975-0144e801d938';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 200g de pollo en dados. Marina 15 minutos en especias tikka (comino, cilantro, garam masala, cúrcuma, jengibre en polvo, ajo en polvo y pimentón).
Paso 2: Dora el pollo marinado en sartén con AOVE a fuego fuerte 5 minutos. Reserva.
Paso 3: Sofríe 1 cebolla picada 5 minutos. Añade 1 tomate troceado y sofríe 4 minutos más.
Paso 4: Agrega 200ml de leche de coco y 1 cda de pasta de tomate. Cuece 5 minutos.
Paso 5: Devuelve el pollo y cuece a fuego medio 10 minutos hasta que la salsa espese.
Paso 6: Cuece 150g de arroz basmati según instrucciones. Sirve el pollo tikka sobre el arroz con cilantro fresco.
Consejo: Cuanto más tiempo marine el pollo, más intenso es el sabor de las especias. Si tienes tiempo, marina en nevera durante 4-8 horas.$ins$ WHERE id = '79e55b0d-103d-4e3e-9895-9e4227b8622a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia 300g de pulpo y golpéalo varias veces contra la encimera para ablandar (o usa pulpo congelado-descongelado, ya está ablandado).
Paso 2: Cuece el pulpo en olla con agua sin sal 35-40 minutos. Comprueba la terneza pinchando la pata más gruesa: debe entrar con facilidad.
Paso 3: Deja enfriar en su caldo. Corta las patas en rodajas de 1 cm con tijeras de cocina.
Paso 4: Cuece 200g de patatas con piel en agua con sal 20 minutos. Pela y corta en rodajas.
Paso 5: Coloca las patatas en un plato de madera o fuente. Distribuye el pulpo encima.
Paso 6: Aliña con sal gruesa, pimentón dulce y picante mezclados, y un generoso chorro de AOVE de calidad.
Consejo: El pulpo congelado ahorra el paso del ablandamiento y queda igual de tierno: el hielo rompe las fibras musculares durante la congelación.$ins$ WHERE id = '5226b693-df15-4a17-969d-8bc2aed3898a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Limpia y trocéa 150g de setas mixtas (shiitake, portobello, champiñones) en trozos irregulares.
Paso 2: Calienta 1 cda de AOVE en sartén a fuego muy fuerte. Añade las setas en una capa sin amontonar.
Paso 3: Deja que se doren 2-3 minutos sin moverlas. Después remueve y dora 2 minutos más.
Paso 4: Añade 50g de jamón ibérico en tiras y 1 diente de ajo picado. Saltea 1 minuto.
Paso 5: Baja el fuego al mínimo. Bate 3 huevos con sal y pimienta y vierte sobre las setas. Remueve suavemente con espátula de silicona 2 minutos.
Paso 6: Retira del fuego cuando aún esté cremoso. Espolvorea perejil picado y sirve inmediatamente.
Consejo: Las setas necesitan espacio y calor fuerte para dorarse. Si las amontonas en la sartén, se cuecen en su propio vapor y quedan blandas y sin color.$ins$ WHERE id = '7a21a453-bafc-4280-a79c-d4cbe9d4a163';

UPDATE recetas SET instrucciones = $ins$Paso 1: Hidrata 300g de setas mixtas en agua tibia si son secas, o limpia y lamina si son frescas. Pica 1 cebolla y 2 dientes de ajo.
Paso 2: Sofríe la cebolla y el ajo en 2 cdas de mantequilla a fuego medio 5 minutos.
Paso 3: Añade las setas y saltea 6-8 minutos a fuego fuerte hasta que se doren y suelten toda el agua.
Paso 4: Incorpora 200g de arroz arborio. Remueve 2 minutos para que absorba la grasa. Añade 80ml de vino blanco y mezcla hasta evaporar.
Paso 5: Añade 600-700ml de caldo caliente de a cucharones, añadiendo el siguiente cuando se absorba el anterior. Cuece 18 minutos removiendo constantemente.
Paso 6: Fuera del fuego añade parmesano rallado generoso y 1 cda de mantequilla fría. Mezcla con vigor. Sirve inmediatamente.
Consejo: El risotto debe servirse al momento: espera 2 minutos y la textura cambia completamente. El caldo debe estar caliente mientras cocinas: el caldo frío interrumpe la cocción del arroz.$ins$ WHERE id = 'a9387126-f18e-44e6-b97b-4e49a21294e1';

UPDATE recetas SET instrucciones = $ins$Paso 1: Separa las hojas de 1 col verde, blanquéalas 3 minutos en agua hirviendo y escurre. Cuece 80g de arroz 10 minutos. Escurre.
Paso 2: Sofríe 1 cebolla picada en AOVE 5 minutos. Mezcla con 300g de carne picada mixta, el arroz semicocido, sal, pimienta y orégano.
Paso 3: Coloca 2-3 cdas de relleno en cada hoja de col. Dobla los lados y enrolla formando paquetitos compactos.
Paso 4: Sofríe 1 tomate triturado con ajo en la misma cazuela 3 minutos. Añade 200ml de agua o caldo.
Paso 5: Coloca los rollitos en la cazuela, juntos para que no se abran. Tapa y cuece a fuego bajo 30 minutos.
Paso 6: Sirve los rollitos con la salsa de tomate por encima.
Consejo: Blanquear las hojas de col las vuelve maleables para enrollar sin que se rompan. No las cuezas más de 3 minutos o quedarán demasiado blandas para doblar.$ins$ WHERE id = '8bd8cb21-9b41-4ff7-b1cd-ed3504254c24';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Pela 200g de patatas y córtalas en rodajas de 5mm. Coloca en bandeja, riega con AOVE, sal y romero.
Paso 2: Hornea las patatas 15 minutos mientras preparas el salmón.
Paso 3: Sazona 180g de salmón con sal, pimienta, eneldo fresco y laminas de ajo.
Paso 4: Coloca el salmón sobre las patatas parcialmente cocinadas. Exprime el zumo de medio limón.
Paso 5: Vuelve a hornear 12-14 minutos. El salmón está listo cuando el centro aún está ligeramente rosado.
Paso 6: Sirve directamente de la bandeja con rodajas de limón fresco.
Consejo: Colocar el salmón sobre las patatas los últimos 12-14 minutos permite que las patatas se terminen con los jugos del salmón, dándoles un sabor excepcional.$ins$ WHERE id = '6ff26b43-54d7-433e-85bc-0b6dfa426928';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 150g de arroz jazmín o blanco según instrucciones. Escurre y reserva.
Paso 2: Prepara la salsa teriyaki: mezcla 3 cdas de salsa de soja, 2 cdas de mirin, 1 cda de sake (o vino blanco) y 1 cdta de azúcar moreno.
Paso 3: Sazona 180g de salmón con sal. Dora en sartén antiadherente con unas gotas de aceite 3 minutos por la parte de la piel.
Paso 4: Da la vuelta y vierte la salsa teriyaki. Cuece 3-4 minutos más barnizando el salmón con la salsa que se va espesando.
Paso 5: El salmón está listo cuando la salsa forma un glaseado brillante y el interior es rosado.
Paso 6: Sirve sobre el arroz. Espolvorea sésamo tostado y acompaña con rodajas de lima.
Consejo: La salsa teriyaki debe reducir y caramelizar sobre el pescado. Si añades la salsa demasiado pronto se quema; espera a que el salmón esté casi listo.$ins$ WHERE id = 'a4e7f1a8-0724-450f-8198-90e49a15c927';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pica 1 cebolla, 1 pimiento rojo y 2 dientes de ajo. Sofríe en 2 cdas de AOVE en sartén amplia 6 minutos a fuego medio.
Paso 2: Añade 1 cdta de comino, 1 cdta de pimentón ahumado y media cdta de cayena. Mezcla 30 segundos.
Paso 3: Agrega 400g de tomate triturado, sal y pimienta. Cuece 8-10 minutos a fuego medio hasta que la salsa reduzca y espese.
Paso 4: Prueba y ajusta de sal. La salsa debe estar bien sabrosa.
Paso 5: Haz 4 huecos en la salsa con cuchara. Casca 1 huevo en cada hueco. Tapa la sartén.
Paso 6: Cuece a fuego bajo 5-7 minutos hasta que las claras cuajen pero las yemas queden líquidas. Sirve con pan pita caliente.
Consejo: El truco de la shakshuka perfecta es que la salsa de tomate sea intensa y rica antes de añadir los huevos: ellos no aportan sabor, solo textura.$ins$ WHERE id = '061e57d8-21c8-4f0c-9c31-6595bb2e0c5b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 500g de cebolla en juliana muy fina. Calienta 2 cdas de mantequilla en olla a fuego muy bajo.
Paso 2: Sofríe la cebolla 30 minutos a fuego muy bajo removiendo ocasionalmente hasta que esté completamente dorada y caramelizada. No tengas prisa.
Paso 3: Añade 100ml de vino blanco y sube el fuego. Deja evaporar 2 minutos. Agrega 800ml de caldo de buey y cuece 10 minutos.
Paso 4: Tuesta 2 rebanadas de baguette en el horno o tostadora hasta que estén crujientes.
Paso 5: Vierte la sopa en cuencos aptos para horno. Coloca 1 rebanada de pan tostada encima y cubre con abundante queso gruyère rallado.
Paso 6: Gratina bajo el grill del horno 3-5 minutos hasta que el queso esté dorado y borbujee. Sirve inmediatamente.
Consejo: La caramelización de la cebolla no se puede apresurar: los 30 minutos a fuego bajo son imprescindibles para desarrollar los azúcares naturales y el sabor profundo.$ins$ WHERE id = 'b6076069-ec58-4ab3-bc39-ddf8d9066330';

UPDATE recetas SET instrucciones = $ins$Paso 1: Hierve 400ml de agua o dashi. Mientras, hidrata el wakame en agua fría 5 minutos y córtalo en trozos.
Paso 2: Corta 100g de tofu firme en cubos de 1,5 cm.
Paso 3: Retira la olla del fuego cuando el agua hierva. Disuelve 3 cdas de pasta de miso en el agua caliente removiendo con varilla. Nunca hiervas el miso.
Paso 4: Añade el tofu y el wakame hidratado al caldo de miso.
Paso 5: Sirve inmediatamente en cuencos.
Paso 6: Espolvorea cebollino fresco picado por encima.
Consejo: El miso no debe hervir nunca: destruye las bacterias beneficiosas de la fermentación. Siempre se añade al final con el fuego apagado.$ins$ WHERE id = 'e155428c-1d54-4f39-bf2b-4028e1772fad';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escalda 500g de tomates en agua hirviendo 30 segundos. Enfría en agua con hielo y pélalos. Trocea la pulpa.
Paso 2: Sofríe 1 cebolla y 2 dientes de ajo picados en 2 cdas de AOVE 5 minutos a fuego medio.
Paso 3: Añade los tomates troceados y una pizca de azúcar. Cuece 8 minutos hasta que reduzcan.
Paso 4: Vierte 400ml de caldo de verduras y lleva a ebullición. Cuece 5 minutos más.
Paso 5: Tritura con batidora de mano hasta textura lisa. Ajusta de sal y pimienta.
Paso 6: Sirve con hojas de albahaca fresca, un hilo de AOVE y pan crujiente al lado.
Consejo: Para una sopa de tomate más intensa, usa tomates de pera maduros o de lata de alta calidad: en invierno, los de bote superan a los frescos de invernadero.$ins$ WHERE id = 'ac6e01ca-2b17-4039-aff1-b32ebc9f8600';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Lava 200g de patatas, córtalas en gajos y mezcla con AOVE, sal, romero y ajo en polvo. Hornea 25 minutos.
Paso 2: Saca 180g de entrecot de la nevera 20 minutos antes para que esté a temperatura ambiente.
Paso 3: Seca el filete con papel de cocina. Sazona generosamente con sal gruesa y pimienta negra recién molida solo en el momento de cocinar.
Paso 4: Calienta una sartén de hierro o plancha a fuego máximo hasta que empiece a humear.
Paso 5: Cocina el entrecot 2-3 minutos por lado para punto medio (rosa en el centro). Añade mantequilla, ajo y romero los últimos 30 segundos y baña la carne.
Paso 6: Deja reposar el filete 5 minutos antes de cortar. Sirve con las patatas al romero.
Consejo: Nunca salar la carne con antelación: la sal extrae la humedad y dificulta el sellado. Sazona justo antes de poner en la sartén.$ins$ WHERE id = '87b0d507-0679-4c40-97fd-d1a57993f24f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 150g de pechuga en tiras con comino, pimentón, sal y pimienta. Dora en sartén con AOVE 5 minutos a fuego fuerte. Reserva.
Paso 2: Prepara el guacamole: aplasta 1 aguacate maduro con tenedor. Añade zumo de media lima, sal, tomate picado fino y cilantro.
Paso 3: Calienta 2 tortillas de maíz en la misma sartén sin aceite 1 minuto por lado o directamente sobre la llama del gas 30 segundos.
Paso 4: Extiende el guacamole sobre cada tortilla.
Paso 5: Coloca el pollo encima. Añade tomate picado, jalapeño al gusto y cilantro fresco.
Paso 6: Dobla o enrolla la tortilla. Sirve con rodajas de lima para exprimir.
Consejo: El guacamole se oxida rápidamente. Para evitarlo, guarda el hueso del aguacate en el bol y cubre con film pegado directamente a la superficie del guacamole.$ins$ WHERE id = '00542464-394d-4aa8-84f4-afb75afee066';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 200g de pollo en trozos. Dora en cazuela de barro con AOVE a fuego fuerte 3 minutos por lado. Reserva.
Paso 2: Sofríe 1 cebolla picada en la misma cazuela 5 minutos. Añade las especias marroquíes (comino, cilantro, jengibre, cúrcuma, canela) y remueve 1 minuto.
Paso 3: Añade aceitunas verdes o negras y 1 limón encurtido en cuartos o rallado.
Paso 4: Devuelve el pollo a la cazuela. Añade 150ml de agua o caldo.
Paso 5: Tapa y cuece a fuego bajo 30-35 minutos hasta que el pollo esté muy tierno.
Paso 6: Ajusta de sal. Sirve con cuscús o pan marroquí para mojar en la salsa.
Consejo: El limón encurtido (o preserved lemon) aporta el sabor característico del tajín. Si no tienes, usa la ralladura de 1 limón fresco aunque el sabor será diferente.$ins$ WHERE id = '392422a4-b25a-489a-b733-f4e3295b0e9a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Seca 180g de atún fresco con papel de cocina. Sazona con sal, pimienta y semillas de sésamo presionando para que queden adheridas.
Paso 2: Calienta sartén de hierro o antiadherente a fuego máximo hasta que eche humo.
Paso 3: Añade unas gotas de aceite. Sella el atún 30-45 segundos por cada lado (4 lados). El exterior debe quedar cocinado 2-3mm, el interior completamente crudo.
Paso 4: Retira y enfría en nevera 2 minutos. Corta en lonchas de 1 cm con cuchillo afilado en movimiento de tracción.
Paso 5: Hidrata el wakame 5 minutos y escurre. Prepara la salsa: 2 cdas de soja, 1 de jengibre rallado y 1 cdta de aceite de sésamo.
Paso 6: Sirve el atún sobre una cama de wakame. Vierte la salsa y espolvorea sésamo tostado.
Consejo: El atún para tataki debe ser de primera calidad: azul o rojo de aleta amarilla. El interior crudo es parte del plato, no un error de cocción.$ins$ WHERE id = 'c7617002-71ee-4b12-8563-89302351830e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 200g de ternera en tiras de 1 cm de grosor y 5 cm de largo. Sazona con sal, pimienta y 1 cdta de maicena (ayuda a que la carne quede tierna).
Paso 2: Corta 1 pimiento rojo, 1 verde y 1 cebolla en tiras del mismo tamaño que la carne.
Paso 3: Calienta wok o sartén a fuego muy fuerte. Añade 2 cdas de aceite. Saltea la ternera en una capa 2-3 minutos sin remover. Reserva.
Paso 4: En la misma sartén saltea la cebolla 1 minuto. Añade los pimientos y saltea 2 minutos más.
Paso 5: Devuelve la ternera. Añade 2 cdas de soja, 1 cdta de aceite de sésamo y 1 cdta de jengibre rallado. Saltea 1 minuto.
Paso 6: Sirve inmediatamente con arroz blanco y sésamo tostado.
Consejo: La maicena en la carne crea una capa protectora que retiene los jugos durante la cocción a fuego fuerte, resultando en una textura mucho más tierna.$ins$ WHERE id = '119d6de9-1493-4cbd-9ea1-9b0a40add752';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela y corta en cubos de 2 cm 300g de patatas. Corta 1 cebolla en juliana. Fríe ambas en abundante AOVE a fuego medio 12-15 minutos hasta que estén tiernas.
Paso 2: Escurre patatas y cebolla en papel de cocina. Sazona con sal.
Paso 3: Bate 4 huevos con sal. Mezcla con las patatas y la cebolla templadas.
Paso 4: En sartén de 22-24 cm con 1 cda de AOVE calienta a fuego medio. Vierte la mezcla. Mueve la sartén en círculos 3 minutos.
Paso 5: Cuando los bordes estén cuajados, cubre con un plato y da la vuelta con decisión. Desliza de nuevo a la sartén.
Paso 6: Cocina 2-3 minutos más. El centro debe estar ligeramente húmedo. Sirve templada.
Consejo: La tortilla española cuaja mejor con el aceite de freír las patatas en lugar de aceite limpio: los sabores impregnan el huevo de forma más profunda.$ins$ WHERE id = '3419b47c-009b-42bd-960e-a4fad4bfa3ad';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Corta 400g de verduras mixtas (pimiento, calabacín, berenjena, cebolla) en trozos de 3 cm.
Paso 2: Coloca en bandeja, riega con 2 cdas de AOVE y espolvorea especias mediterráneas (orégano, tomillo, comino).
Paso 3: Hornea 25-30 minutos removiendo a mitad de tiempo hasta que las verduras estén tiernas y con bordes dorados.
Paso 4: Mientras se hornean, prepara 100g de humus casero o de bote en un bol pequeño.
Paso 5: Saca las verduras del horno. Sirve en plato con el humus al lado como dip.
Paso 6: Riega el humus con un hilo de AOVE y unas semillas de sésamo o pimentón.
Consejo: El humus mejora mucho añadiéndole un chorrito de zumo de limón extra y una pizca de comino fresco justo antes de servir, aunque sea de bote.$ins$ WHERE id = 'addb0d2e-6bdc-4cf2-b231-1f9860eaa7f9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 180g de ternera en tiras finas de 5mm. Sazona con sal, pimienta y 1 cdta de maicena.
Paso 2: Separa 200g de brócoli en ramilletes pequeños. Lamina 2 dientes de ajo. Ralla 1 cdta de jengibre fresco.
Paso 3: Calienta wok a fuego muy fuerte hasta que humee. Añade 2 cdas de aceite.
Paso 4: Saltea la ternera en una capa 1-2 minutos. Reserva. En la misma sartén saltea el brócoli 3 minutos.
Paso 5: Devuelve la ternera. Añade ajo, jengibre, 2 cdas de soja y 1 cdta de aceite de sésamo. Saltea 1 minuto mezclando bien.
Paso 6: Sirve inmediatamente con arroz blanco y sésamo tostado.
Consejo: El brócoli al wok debe quedar verde brillante y con mordida. Si empieza a ponerse amarillo-opaco, está sobrecocinado y pierde nutrientes y textura.$ins$ WHERE id = 'd9d6faa2-da0a-4d73-9c26-1e8a8d108fdb';

UPDATE recetas SET instrucciones = $ins$Paso 1: Sazona 150g de pechuga de pollo en tiras con sal, pimienta, pimentón y comino.
Paso 2: Dora el pollo en sartén con 1 cda de AOVE a fuego fuerte 5 minutos hasta que esté bien cocinado. Reserva.
Paso 3: Prepara el guacamole: aplasta 1 aguacate con tenedor, añade sal, zumo de lima y cilantro picado.
Paso 4: Calienta 1 tortilla integral en la plancha o directamente sobre el fuego 30 segundos por lado.
Paso 5: Extiende el guacamole sobre la tortilla. Añade el pollo, lechuga, tomate en dados y maíz dulce.
Paso 6: Enrolla la tortilla apretando bien. Córtala por la mitad en diagonal.
Consejo: Para que el wrap no se abra, no pongas demasiado relleno y asegúrate de que el guacamole sirve como pegamento untado en todo el interior de la tortilla.$ins$ WHERE id = 'd910acc6-6aad-4f36-8dd5-cda5665aeb49';

UPDATE recetas SET instrucciones = $ins$Paso 1: La noche anterior, pon en un tarro de 400ml: 80g de copos de avena, 200ml de leche (o vegetal) y 100g de yogur natural.
Paso 2: Pela 1 plátano y aplástalo con tenedor hasta hacer un puré. Mézclalo con la avena.
Paso 3: Añade 1 cdta de semillas de chía. Remueve todo bien.
Paso 4: Tapa el tarro y refrigera toda la noche (mínimo 6 horas, máximo 3 días).
Paso 5: A la mañana siguiente, saca el tarro y remueve. Si está muy espeso, añade un chorrito de leche.
Consejo: Puedes preparar 3-4 tarros el domingo para toda la semana. Añade los toppings frescos (frutas, frutos secos) siempre en el momento de comer.$ins$ WHERE id = '2e8fc795-365b-44af-b464-e852bb375448';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Pela 1 manzana y córtala en dados pequeños de 1 cm.
Paso 2: Bate 1 huevo en un bol. Añade 80g de avena, 200ml de leche, los dados de manzana, 1 cdta de canela y media de nuez moscada.
Paso 3: Vierte la mezcla en una fuente de horno pequeña engrasada con un poco de mantequilla.
Paso 4: Hornea 25 minutos hasta que la superficie esté dorada y al insertar un palillo salga limpio.
Paso 5: Deja templar 5 minutos. Corta en porciones y sirve directamente del molde.
Consejo: Sustituye la manzana por pera, melocotón o plátano según la temporada. La avena horneada se guarda 3 días en nevera y se recalienta en 1 minuto en el microondas.$ins$ WHERE id = 'b433a7be-47c7-473f-b9e0-257f1742d6f8';

UPDATE recetas SET instrucciones = $ins$Paso 1: Abre el bagel integral por la mitad y tuéstalo en la tostadora o plancha hasta que esté dorado y crujiente.
Paso 2: Extiende queso crema generosamente sobre cada mitad del bagel.
Paso 3: Coloca 100g de salmón ahumado encima del queso crema.
Paso 4: Escurre bien 1 cdta de alcaparras y dispón encima del salmón.
Paso 5: Añade unas láminas finas de cebolla morada o pepino si tienes. Espolvorea eneldo fresco.
Consejo: El salmón ahumado tiene mucha sal. Si usas queso crema sin sal, el conjunto queda perfectamente equilibrado. No añadas sal extra.$ins$ WHERE id = '05adc2b7-bea7-4057-98c6-896378744e1c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 150g de fresas, retira el cáliz verde y córtalas en trozos.
Paso 2: Pon en la batidora: 1 scoop de proteína de vainilla (unos 30g), las fresas troceadas y 200ml de leche fría.
Paso 3: Añade 4-5 cubitos de hielo.
Paso 4: Tritura a máxima potencia 30-45 segundos hasta que quede completamente liso y sin grumos.
Paso 5: Prueba de dulzor. Si quieres más dulce, añade media cdta de miel y tritura 5 segundos más.
Consejo: Para un batido más espeso y cremoso, usa fresas congeladas en lugar de frescas: eliminan la necesidad del hielo y la textura es mucho más densa.$ins$ WHERE id = 'cbe77955-b03b-4bcc-b01e-c031e01127b1';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 1 plátano maduro y trocéalo.
Paso 2: Pon en la batidora: 1 scoop de proteína de chocolate, el plátano troceado y 200ml de leche desnatada fría.
Paso 3: Añade 4-5 cubitos de hielo.
Paso 4: Tritura a máxima potencia 30-45 segundos hasta que quede completamente liso.
Paso 5: Sirve inmediatamente en un vaso alto. Puedes decorar con cacao en polvo sin azúcar espolvoreado.
Consejo: El plátano más maduro (con manchas marrones) aporta más dulzor natural, lo que permite reducir o eliminar cualquier edulcorante añadido.$ins$ WHERE id = 'ca6bb857-86c0-4e43-89e7-c0b4a026cf8e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 2 manzanas, retira el corazón y trocéalas (con piel si son orgánicas).
Paso 2: Lava bien 100g de espinacas frescas.
Paso 3: Exprime el zumo de 1 limón. Pela un trozo de jengibre fresco de 1 cm.
Paso 4: Pon en la batidora: manzanas, espinacas, zumo de limón, jengibre y 200ml de agua fría.
Paso 5: Tritura a máxima potencia 1 minuto hasta que quede liso. Sirve inmediatamente.
Consejo: El limón es esencial en este batido: equilibra el sabor de las espinacas y aporta vitamina C que mejora la absorción del hierro de las espinacas.$ins$ WHERE id = 'f9ac012a-39c5-4460-9892-ec392f9c21eb';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Pela 2 manzanas y córtalas en dados pequeños.
Paso 2: En un bol grande mezcla: 100g de avena molida (pasa los copos por la batidora), 1 cdta de levadura química y 1 cdta de canela.
Paso 3: En otro bol bate 2 huevos. Añade los dados de manzana.
Paso 4: Une los ingredientes secos y húmedos. Mezcla hasta obtener una masa homogénea. No batas en exceso.
Paso 5: Vierte en molde de plum cake engrasado con papel de horno.
Paso 6: Hornea 22-25 minutos. Está listo cuando al insertar un palillo en el centro salga limpio.
Consejo: Este bizcocho sin azúcar añadido sabe más dulce al día siguiente: las manzanas liberan sus azúcares naturales y humedecen el interior durante el reposo.$ins$ WHERE id = 'ab1f9194-2b4c-478b-aada-5fd69ff345f2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Abre 1 chapata integral por la mitad. Tuéstala en la sartén con unas gotas de AOVE o en la tostadora.
Paso 2: Bate en un bol 3 claras de huevo con 1 huevo entero, sal y pimienta.
Paso 3: Cuaja el revuelto en sartén antiadherente a fuego bajo durante 2-3 minutos removiendo suavemente. Retira cuando esté cremoso.
Paso 4: Coloca 2 lonchas de pavo cocido sobre la mitad inferior del pan.
Paso 5: Añade el revuelto de claras encima del pavo.
Paso 6: Coloca rodajas finas de tomate y hojas de rúcula. Cierra con la otra mitad del pan.
Consejo: El revuelto de claras tiene menos calorías y grasa que el de huevo entero, pero añadir 1 huevo entero mejora mucho el sabor y la textura.$ins$ WHERE id = 'ff58e8dd-dca3-4648-a852-9a052ee98ae2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca el açaí congelado del congelador y déjalo 2 minutos fuera para que se ablande ligeramente.
Paso 2: Pela y trocéa 1 plátano congelado (guarda siempre plátanos pelados en el congelador).
Paso 3: Pon en la batidora: açaí troceado, plátano congelado y 100ml de leche de coco. Tritura hasta textura espesa tipo helado.
Paso 4: Vierte en un bol. La consistencia debe ser espesa, no líquida. Si queda muy líquida, usa menos leche.
Paso 5: Coloca encima los toppings: frutas frescas en láminas (kiwi, mango, fresas), granola y un hilo de miel.
Consejo: La clave del smoothie bowl es la consistencia: debe ser tan espeso que puedas comerlo con cuchara. Para lograrlo usa frutas bien congeladas y muy poca leche.$ins$ WHERE id = 'd397f931-8725-4a83-b096-9bfaf6efe39f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava y corta 200g de frutas variadas de temporada (fresas, mango, kiwi, arándanos) en trozos del tamaño de un bocado.
Paso 2: Coloca la fruta en un bol o taza.
Paso 3: Exprime el zumo de 1 naranja directamente sobre la fruta.
Paso 4: Espolvorea 1 cda de semillas de chía por encima.
Paso 5: Añade unas hojas de menta fresca para aromatizar. Sirve inmediatamente.
Consejo: Las semillas de chía absorben líquido: si dejas reposar 10 minutos forman un gel nutritivo alrededor de la fruta que hace el desayuno más saciante.$ins$ WHERE id = '2a06f6b4-29a5-42c9-a109-b88ddbe33e74';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lleva 250ml de leche a ebullición en un cazo pequeño a fuego medio.
Paso 2: Cuando empiece a hervir, vierte 60g de sémola de trigo (o semolina) en lluvia mientras remueves constantemente con varilla.
Paso 3: Baja el fuego al mínimo y cuece 3-4 minutos sin parar de remover hasta que espese.
Paso 4: Retira del fuego. Si tienes proteína en polvo de sabor neutro o vainilla, mézclala ahora.
Paso 5: Vierte en un bol. Deja templar 2 minutos.
Paso 6: Sirve con 1 cda de mermelada sin azúcar, frutas frescas o miel por encima.
Consejo: Añade la sémola siempre mientras remueves y en lluvia fina: si la echas de golpe se forman grumos imposibles de deshacer sin batidora.$ins$ WHERE id = '59d18bcb-baec-4c62-867b-74e6cc4bae4a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Aplasta con un tenedor 2 plátanos muy maduros (con manchas negras) en un bol hasta hacer un puré liso.
Paso 2: Añade 80g de copos de avena y 2 cdas de cacao en polvo sin azúcar. Mezcla bien.
Paso 3: Agrega 20g de chocolate negro troceado en trozos pequeños.
Paso 4: Mezcla todo hasta obtener una masa homogénea y maleable.
Paso 5: Extiende en un recipiente o bandeja pequeña forrada con papel. Nivela la superficie con la cuchara.
Paso 6: Refrigera 30 minutos. Corta en porciones cuadradas. Guarda en nevera hasta 3 días.
Consejo: Cuanto más maduros estén los plátanos, más dulce y más fácil de moldear será la masa. Usa solo plátanos con la piel casi negra para el resultado óptimo.$ins$ WHERE id = 'c02a23ed-95f4-409b-8784-5bb361f6a87a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 60g de copos de maíz sin azúcar en un bol amplio.
Paso 2: Vierte 300ml de leche desnatada fría directamente sobre los copos.
Paso 3: Lava y prepara la fruta fresca: rodajas de plátano, fresas partidas o arándanos.
Paso 4: Coloca la fruta encima de los copos.
Paso 5: Sirve inmediatamente antes de que los copos se ablanden si prefieres textura crujiente.
Consejo: Para desayunos con prisas, esta es la opción más rápida. Lee siempre el etiquetado: algunos copos de maíz "sin azúcar" llevan más de 10g de azúcar por 100g. Busca menos de 5g.$ins$ WHERE id = '5d192a00-c30f-4dd6-8477-8ea976e9c993';

UPDATE recetas SET instrucciones = $ins$Paso 1: Mezcla en un bol: 100g de harina de trigo sarraceno, 1 pizca de sal y 200ml de leche. Bate con varilla hasta que no haya grumos.
Paso 2: Añade 2 huevos batidos y mezcla bien. La masa debe ser fluida como la nata líquida.
Paso 3: Deja reposar la masa 5 minutos.
Paso 4: Calienta una sartén antiadherente de 20 cm con unas gotas de aceite. Cuando esté caliente, vierte un cacillo de masa y extiende girando la sartén.
Paso 5: Cocina 1-2 minutos hasta que los bordes estén secos y el crepe se despegue fácilmente. Da la vuelta y cocina 30 segundos más.
Paso 6: Sirve con plátano en rodajas, miel o mermelada sin azúcar.
Consejo: El trigo sarraceno no tiene gluten y aporta más proteína que la harina de trigo. Los crepes quedan más oscuros y con sabor ligeramente a nuez.$ins$ WHERE id = 'e1e2f109-55ae-44d3-99e2-305771259e78';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Pela 2 peras maduras y córtalas en dados de 1,5 cm.
Paso 2: Coloca las peras en una fuente de horno. Espolvorea con canela y 1 cdta de miel.
Paso 3: Mezcla en un bol: 80g de copos de avena, 30g de nueces troceadas, 1 cdta de miel y 1 cda de mantequilla fundida.
Paso 4: Extiende la mezcla de avena sobre las peras formando el crumble.
Paso 5: Hornea 18-20 minutos hasta que el crumble esté dorado y crujiente y las peras estén tiernas.
Paso 6: Sirve caliente con un poco de yogur griego al lado.
Consejo: El crumble se puede preparar con cualquier fruta de temporada: manzana, melocotón, ciruela. El principio es siempre el mismo: fruta en la base, avena encima.$ins$ WHERE id = 'e6ac8207-cf2c-4ea6-938a-41c80ecf5fd3';

UPDATE recetas SET instrucciones = $ins$Paso 1: Calienta 1 sartén a fuego medio. Añade 2 lonchas de pavo cocido y dóralas 1 minuto por lado hasta que estén ligeramente crujientes.
Paso 2: En otra sartén pequeña antiadherente con 1 cdta de AOVE, fríe 2 huevos a fuego medio-bajo. La clara debe cuajar completamente y la yema quedar líquida.
Paso 3: Corta 1 tomate en rodajas de 1 cm. Limpia y lamina unos champiñones.
Paso 4: Saltea los champiñones en la sartén del pavo 3 minutos hasta que estén dorados.
Paso 5: Tuesta 1 rebanada de pan integral.
Paso 6: Sirve todo junto en el plato: pavo, huevos fritos, tomate, champiñones y tostada.
Consejo: Para los champiñones perfectos, necesitan la sartén muy caliente y no se mueven los primeros 2 minutos. Así se doran en vez de cocer en su propio agua.$ins$ WHERE id = 'dc1b3b06-8972-45c7-a1fd-b2c01d1a2656';

UPDATE recetas SET instrucciones = $ins$Paso 1: Cuece 2 huevos en agua hirviendo durante 10 minutos. Enfría en agua con hielo y pela.
Paso 2: Corta 1 tomate maduro en rodajas. Corta el pepino en rodajas. Prepara aceitunas negras o verdes.
Paso 3: Desmiga 80g de queso feta en trozos.
Paso 4: Parte los huevos por la mitad.
Paso 5: Monta el plato: coloca todas las verduras, el queso y los huevos en el plato de forma armoniosa.
Paso 6: Aliña con 1 cda de AOVE, una pizca de orégano seco, sal marina y pimienta negra.
Consejo: Este desayuno mediterráneo aporta proteína completa (huevo) y proteína láctea (feta), grasas saludables (AOVE) y antioxidantes (tomate). Completo y equilibrado.$ins$ WHERE id = '5780a9d9-1a80-4aa9-b7b0-ec337b2b5a9b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Pica pimiento, cebolla y calabacín en dados pequeños.
Paso 2: Sofríe las verduras en 1 cda de AOVE en sartén apta para horno 5 minutos a fuego medio.
Paso 3: Bate 4 huevos con sal, pimienta y albahaca seca. Añade 30g de queso rallado.
Paso 4: Vierte los huevos sobre las verduras en la sartén. Asegúrate de que las verduras están bien distribuidas.
Paso 5: Cocina a fuego bajo 2 minutos en la vitrocerámica hasta que los bordes empiecen a cuajar.
Paso 6: Traslada la sartén al horno y hornea 12-14 minutos hasta que el centro esté completamente cuajado y la superficie dorada.
Consejo: La frittata es la tortilla italiana que se termina en el horno. Sirve fría o caliente: aguanta perfectamente 2 días en nevera cortada en porciones.$ins$ WHERE id = '56e9309b-c038-47e3-a9fd-f8564f00151d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 160°C. Mezcla en bol: 50g de copos de avena, 20g de almendras laminadas, 20g de miel y 1 cdta de AOVE.
Paso 2: Extiende la mezcla en bandeja con papel de horno formando una capa uniforme.
Paso 3: Hornea 15-18 minutos removiendo cada 5 minutos hasta que esté dorada. Cuidado: se quema fácilmente.
Paso 4: Saca del horno y deja enfriar completamente sin tocarla: al enfriarse se vuelve crujiente.
Paso 5: Sirve 40g de granola sobre 200g de yogur griego. No mezcles la granola hasta el momento de comer.
Consejo: La granola se guarda en tarro hermético hasta 3 semanas. Prepara una cantidad mayor los fines de semana para toda la semana: es mucho más económica y sin aditivos que la de bote.$ins$ WHERE id = '3bbaa1ee-47bb-4d20-9869-fc9d293584ea';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C o usa la plancha del horno.
Paso 2: Lava 8 espárragos y rompe el extremo duro. Colócalos en bandeja con papel de horno.
Paso 3: Riega con 1 cdta de AOVE y sazona con sal y pimentón.
Paso 4: Hornea los espárragos 8-10 minutos hasta que estén tiernos y con los bordes ligeramente tostados.
Paso 5: Mientras se hornean, calienta 1 cda de AOVE en cazuelita. Casca 2 huevos directamente. Cocina a fuego bajo hasta que la clara esté cuajada y la yema líquida (3-4 min).
Paso 6: Sirve los huevos al plato acompañados de los espárragos asados.
Consejo: Los huevos al plato quedan perfectos cocinados a fuego bajo y sin tapa: la clara cuaja lentamente sin que la yema pierda su brillo líquido.$ins$ WHERE id = '38a17f2e-2906-4633-b245-ee7af46357ca';

UPDATE recetas SET instrucciones = $ins$Paso 1: Hierve agua en olla amplia. Añade un chorrito de vinagre blanco (ayuda a que el huevo mantenga su forma).
Paso 2: Tuesta 2 muffins ingleses partidos por la mitad. Asa 6 espárragos en plancha con AOVE 3 minutos.
Paso 3: Prepara la salsa holandesa rápida: bate 2 yemas con zumo de limón en bol sobre agua caliente sin que hierva. Añade mantequilla fundida poco a poco batiendo hasta espesar.
Paso 4: Baja el agua a fuego muy suave. Forma un remolino con cuchara. Casca 1 huevo y sumérgelo suavemente. Cuece 3 minutos.
Paso 5: Coloca 3 espárragos sobre cada muffin. Saca el huevo con espumadera y coloca encima.
Paso 6: Vierte la salsa holandesa por encima. Espolvorea pimentón y sirve inmediatamente.
Consejo: El huevo escalfado necesita que el agua esté en movimiento (el remolino) para que la clara rodee la yema. Si el agua hierve fuerte, el huevo se desintegra.$ins$ WHERE id = 'a4e363af-1978-4aba-962d-77fb79934006';

UPDATE recetas SET instrucciones = $ins$Paso 1: Casca 3 huevos en un bol. Añade sal y pimienta negra. Bate ligeramente con tenedor (no demasiado).
Paso 2: Corta 80g de salmón ahumado en tiras o trozos.
Paso 3: Derrite 1 nuez de mantequilla en sartén antiadherente a fuego muy bajo.
Paso 4: Cuando la mantequilla empiece a espumar, vierte los huevos batidos. Remueve con espátula de silicona haciendo movimientos lentos de pliegue.
Paso 5: Cuando el revuelto empiece a cuajar pero aún esté cremoso (2-3 min), incorpora el salmón y mezcla suavemente.
Paso 6: Retira del fuego con el revuelto aún ligeramente húmedo. Espolvorea cebollino picado y sirve inmediatamente.
Consejo: Los huevos revueltos perfectos se cocinan a fuego mínimo y se retiran cuando parece que les falta 30 segundos: el calor de la sartén los termina solos.$ins$ WHERE id = '3e735299-69aa-4126-955c-67d7d582644f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Agita bien el bote de kéfir antes de abrir. Vierte 200ml en un vaso.
Paso 2: Pon 40g de cereales sin azúcar en un bol.
Paso 3: Vierte el kéfir sobre los cereales o sirve el kéfir en vaso separado para beberlo mientras comes los cereales.
Paso 4: Coloca 20g de almendras crudas enteras o laminadas encima.
Paso 5: Espolvorea una pizca de canela.
Consejo: El kéfir tiene más probióticos que el yogur convencional y mejor digestibilidad de la lactosa. Si no toleras la leche normal, el kéfir suele asentarse mejor.$ins$ WHERE id = '0ffb0a9b-e9fb-4ded-8b66-c55c1a2561fc';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 2 kiwis y córtalos en rodajas de 1 cm.
Paso 2: Coloca el kiwi en un bol o plato.
Paso 3: Añade 150g de queso fresco batido 0% encima o al lado del kiwi.
Paso 4: Vierte 1 cdta de miel por encima del queso fresco.
Paso 5: Sirve inmediatamente.
Consejo: El kiwi es una de las frutas con más vitamina C: 1 kiwi aporta más vitamina C que una naranja entera. Cómelo con la piel fina lavada para doblar la fibra.$ins$ WHERE id = 'c588d6c9-5013-4bef-bb2b-1fa43b99602d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 60g de muesli en un bol.
Paso 2: Lava 100g de frutas del bosque (arándanos, fresas, frambuesas). Si están congeladas, descongela 5 minutos.
Paso 3: Vierte 200ml de leche fría sobre el muesli.
Paso 4: Añade las frutas del bosque encima.
Paso 5: Vierte 1 cdta de miel si necesitas más dulzor. Sirve inmediatamente.
Consejo: El muesli sin tostar (a diferencia de la granola) no lleva azúcares añadidos del tostado. Lee siempre el etiquetado: el muesli de calidad solo tiene cereales, frutos secos y frutas secas.$ins$ WHERE id = 'a1d5625f-75d8-4813-a4dd-78921c058b04';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 180°C. Prepara un molde de muffins (6 cavidades) con cápsulas de papel.
Paso 2: Mezcla en bol grande: 100g de avena molida (pasa los copos por la batidora), 1 cdta de levadura y 1 pizca de sal.
Paso 3: En otro bol bate 2 huevos con 2 cdas de miel y 100ml de leche.
Paso 4: Une ingredientes secos y húmedos. Añade 100g de arándanos frescos o congelados y mezcla suavemente.
Paso 5: Rellena las cápsulas hasta tres cuartos de su capacidad.
Paso 6: Hornea 20-22 minutos. Están listos cuando al insertar un palillo salga limpio y la superficie esté dorada.
Consejo: Los muffins de avena no suben tanto como los de harina de trigo: es normal. Se mantienen jugosos 3 días en recipiente hermético y 1 mes en el congelador.$ins$ WHERE id = 'bb42e40f-5078-48a1-a0dc-32651c30938f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Mezcla en un bol: 80g de harina de avena (copos triturados), 1 scoop de proteína de vainilla y 1 pizca de sal.
Paso 2: En otro bol bate 2 huevos con 100ml de leche.
Paso 3: Une ingredientes secos y húmedos. La masa debe quedar como la de los crepes: fluida pero no aguada.
Paso 4: Calienta sartén antiadherente de 18 cm con 1 cdta de AOVE. Cuando esté caliente vierte la mitad de la masa.
Paso 5: Cocina a fuego medio 2-3 minutos hasta que aparezcan burbujas en la superficie y los bordes se sequen. Da la vuelta y cocina 1-2 minutos más.
Paso 6: Repite con el resto de la masa. Sirve con frutas del bosque y miel.
Consejo: Añadir proteína en polvo espesa la masa. Si está demasiado densa, añade leche de a cucharadas hasta obtener la consistencia de crepe. La proteína no debe grumear: mezcla bien con los secos antes de añadir los líquidos.$ins$ WHERE id = '63098958-5cf1-46e6-aa32-d95d4971b1c7';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 200g de yogur griego en un vaso alto o bol.
Paso 2: Añade 40g de granola por encima del yogur.
Paso 3: Lava 80g de fresas y córtalas en rodajas. Lava 20g de arándanos.
Paso 4: Coloca las fresas en rodajas encima de la granola.
Paso 5: Añade los arándanos. Sirve inmediatamente para que la granola conserve su textura crujiente.
Consejo: La granola se humedece en contacto con el yogur en pocos minutos. Si te gusta crujiente, añádela justo en el momento de comer, nunca antes.$ins$ WHERE id = '44bfa3d6-0bff-41ff-895e-d403d1b90f3c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 80g de copos de avena en un cazo con 200ml de leche a fuego medio.
Paso 2: Calienta removiendo constantemente con cuchara de madera hasta que la avena absorba la leche y espese (4-5 minutos).
Paso 3: Pela 1 plátano y aplástalo con tenedor hasta hacer un puré. Incorpora a la avena y remueve bien.
Paso 4: Si está muy espesa, añade un chorrito más de leche caliente hasta la consistencia deseada.
Paso 5: Vierte en un bol. Añade 1 cdta de miel y espolvorea canela generosamente.
Paso 6: Sirve caliente. Puedes añadir unas rodajas de plátano fresco por encima.
Consejo: El plátano aplastado dentro del porridge lo endulza de forma natural y le da cremosidad. Cuanto más maduro el plátano, más dulce y suave el resultado.$ins$ WHERE id = '96ce3cd0-132e-467c-94b2-bd70e8f5212f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 80g de copos de avena con 250ml de leche en un cazo a fuego medio.
Paso 2: Remueve constantemente 4-5 minutos hasta que la avena absorba la leche y quede cremosa.
Paso 3: Retira del fuego. Si tienes proteína en polvo, añade 1 scoop y mezcla con energía hasta que se disuelva sin grumos.
Paso 4: Añade 2 cdas de mantequilla de cacahuete natural y mezcla bien hasta que se integre.
Paso 5: Si está demasiado espesa, añade un chorrito de leche caliente.
Paso 6: Sirve en bol con un chorrito más de mantequilla de cacahuete encima y unas rodajas de plátano.
Consejo: Añade el scoop de proteína siempre fuera del fuego: la proteína coagula con el calor excesivo y forma grumos difíciles de deshacer.$ins$ WHERE id = 'c906ff2a-c009-44a9-bf99-2bd6aa3979ad';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 4 cdas de semillas de chía en un tarro o bol.
Paso 2: Vierte 200ml de leche de coco. Añade 1 cdta de extracto de vainilla y 1 cdta de miel o sirope de agave si quieres dulzor.
Paso 3: Remueve bien con tenedor durante 1 minuto para que las semillas se distribuyan uniformemente.
Paso 4: Deja reposar 5 minutos y remueve de nuevo (evita que las semillas se aglomeren en el fondo).
Paso 5: Tapa y refrigera mínimo 2 horas o toda la noche hasta que forme una textura de budín.
Paso 6: Pela 1 mango y córtalo en dados. Sirve el pudín con el mango fresco encima.
Consejo: Las semillas de chía absorben hasta 10 veces su peso en líquido. Si el pudín queda muy líquido tras 2 horas, añade 1 cda más de chía y espera 30 minutos más.$ins$ WHERE id = '4a6c0e5c-a3b5-4232-9617-e235760b1f9b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca 200g de queso cottage de la nevera.
Paso 2: Pela 1 melocotón maduro y córtalo en gajos o dados.
Paso 3: Coloca el queso cottage en un bol.
Paso 4: Añade los gajos de melocotón encima.
Paso 5: Vierte 1 cdta de miel por encima. Sirve inmediatamente.
Consejo: El queso cottage tiene el doble de proteína que el yogur griego con menos calorías. Su sabor es neutro y combina con frutas ácidas como el melocotón o la piña perfectamente.$ins$ WHERE id = 'a8003bfa-0dbe-42d8-8806-fad5a2ad0f24';

UPDATE recetas SET instrucciones = $ins$Paso 1: Casca 3 huevos en un bol. Añade sal y pimienta. Bate ligeramente.
Paso 2: Lamina muy fina 10g de trufa negra fresca con mandolina o cuchillo muy afilado.
Paso 3: Derrite 1 nuez de mantequilla en sartén antiadherente a fuego muy bajo.
Paso 4: Cuando la mantequilla empiece a espumar pero no se queme, vierte los huevos. Remueve con espátula de silicona muy lentamente.
Paso 5: Cuando el revuelto esté casi cuajado pero aún muy cremoso (2-3 min), incorpora las láminas de trufa y mezcla suavemente.
Paso 6: Retira del fuego antes de que cuaje del todo. Espolvorea cebollino y sirve inmediatamente.
Consejo: La trufa libera su aroma con el calor del huevo pero se destruye si se cocina demasiado. Añádela al final con el fuego apagado para preservar todo su perfume.$ins$ WHERE id = '64115963-7a74-4a50-a088-4a2345a2326c';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 100g de espinacas frescas. Pela y trocéa 1 plátano congelado.
Paso 2: Pon en la batidora: espinacas, plátano congelado y 200ml de leche de avena. Tritura a máxima potencia 1 minuto.
Paso 3: La mezcla debe quedar muy espesa, similar al helado blando. Si es demasiado líquida, añade más plátano congelado.
Paso 4: Vierte en un bol.
Paso 5: Decora con toppings: granola, frutas frescas en láminas, coco rallado, semillas de sésamo o cacao en polvo.
Consejo: El plátano congelado es el secreto de la textura cremosa del smoothie bowl. Pela los plátanos maduros, córtalos en trozos y congélalos: siempre tendrás base para un bowl en 2 minutos.$ins$ WHERE id = 'c6056d7d-8e36-4a74-95a4-f83c1b5dd710';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 1 mango maduro y córtalo en trozos.
Paso 2: Pon en la batidora: los trozos de mango, 200ml de leche de coco, el zumo de 1 lima y 1 trozo de jengibre fresco de 1 cm pelado.
Paso 3: Añade 4-5 cubitos de hielo.
Paso 4: Tritura a máxima potencia 45 segundos hasta que quede completamente liso y espumoso.
Paso 5: Sirve inmediatamente en vaso alto. Decora con una rodaja de lima en el borde.
Consejo: El mango congelado en trozos da más cremosidad y elimina la necesidad del hielo. Compra mangos en temporada, trocéalos y congélalos para tenerlos todo el año.$ins$ WHERE id = '34324589-7a0c-4b5a-970e-a3bf4eec3070';

UPDATE recetas SET instrucciones = $ins$Paso 1: Separa las claras de 6 huevos grandes. Reserva las yemas para otra preparación.
Paso 2: Lava 100g de espinacas y sécalas bien.
Paso 3: Calienta unas gotas de aceite en sartén antiadherente de 18 cm a fuego medio. Añade 1 diente de ajo picado y sofríe 30 segundos.
Paso 4: Añade las espinacas y saltea 1-2 minutos hasta que se reduzcan completamente.
Paso 5: Sazona las claras con sal y vierte sobre las espinacas. Cuece a fuego medio-bajo 2-3 minutos.
Paso 6: Cuando los bordes cuajen, da la vuelta con plato y cocina 1-2 minutos más. Sirve inmediatamente.
Consejo: La tortilla de claras es casi insulsa sin las espinacas. Para compensar el sabor de la yema, añade una pizca de cúrcuma: da color dorado y matiz sabroso.$ins$ WHERE id = '66e9f4eb-5546-4ba7-80cc-c6d4976abccc';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 100g de patata y córtala en láminas finas de 2mm. Pica media cebolla pequeña.
Paso 2: Fríe las láminas de patata y la cebolla en AOVE a fuego medio 8-10 minutos hasta que estén tiernas. Escurre en papel de cocina y sala.
Paso 3: Bate 2 huevos con sal y pimienta.
Paso 4: Mezcla los huevos batidos con la patata y la cebolla fritas.
Paso 5: Calienta 1 cdta de AOVE en sartén de 16 cm a fuego medio-bajo. Vierte la mezcla. Cocina 3 minutos.
Paso 6: Da la vuelta con un plato y cocina 2 minutos más. Sirve templada.
Consejo: La tortilla de patata miniatura es perfecta para una persona. El truco para que quede jugosa es usar solo la cantidad justa de huevo: 1 huevo por cada 50g de patata.$ins$ WHERE id = '4d62cf2d-563d-404e-89e4-2f1443242459';

UPDATE recetas SET instrucciones = $ins$Paso 1: Casca 2 huevos en un bol. Añade sal y bate ligeramente con tenedor.
Paso 2: Corta 50g de jamón york en tiras finas.
Paso 3: Calienta 1 cdta de aceite de oliva en sartén antiadherente de 18 cm a fuego medio-alto.
Paso 4: Cuando el aceite esté caliente, vierte los huevos batidos. Mueve la sartén en círculos para que se distribuyan.
Paso 5: Cuando la superficie esté casi cuajada (1-1,5 minutos), coloca el jamón en el centro. Dobla la tortilla por la mitad con espátula.
Paso 6: Desliza a un plato. La tortilla debe quedar dorada por fuera y cremosa por dentro.
Consejo: El secreto de la tortilla francesa perfecta: sartén muy caliente para que la base selle rápido, y retirar del fuego cuando aún parece que le falta 20 segundos.$ins$ WHERE id = '36dc4313-b2c3-408f-aded-3c147280758f';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 1 plátano grande muy maduro (con manchas negras) y aplástalo completamente con tenedor hasta hacer un puré sin grumos.
Paso 2: Casca 2 huevos y añádelos al puré de plátano. Mezcla bien con tenedor o varilla.
Paso 3: Añade una pizca de canela si quieres. La masa debe quedar fluida.
Paso 4: Calienta sartén antiadherente a fuego medio con unas gotas de aceite.
Paso 5: Vierte pequeñas porciones de masa (2-3 cdas por tortita). Cocina 2 minutos hasta que aparezcan burbujas en la superficie.
Paso 6: Da la vuelta con espátula y cocina 1 minuto más. Repite con el resto de la masa. Sirve con miel o frutas.
Consejo: Esta receta de solo 2 ingredientes es la más viral de la cocina fitness. El plátano sustituye a la harina y el azúcar a la vez. Cuanto más maduro, mejor resultado.$ins$ WHERE id = '19f805e7-f574-48d4-a673-f93903f6e897';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 1 aguacate maduro. Córtalo por la mitad, extrae el hueso y aplasta la pulpa con tenedor.
Paso 2: Añade zumo de medio limón, sal y pimienta al aguacate aplastado. Mezcla bien.
Paso 3: Tuesta 2 rebanadas de pan integral en la tostadora hasta que estén bien doradas.
Paso 4: Extiende la crema de aguacate generosamente sobre cada tostada.
Paso 5: Espolvorea las semillas: girasol, calabaza y sésamo mezclados.
Consejo: El aguacate se oxida rápidamente al contacto con el aire. El zumo de limón lo protege durante unos 30 minutos. No prepares la crema con mucha antelación.$ins$ WHERE id = '843fec23-52cb-490b-9a7b-d48841a24e2d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan bueno (masa madre o integral) hasta que estén bien doradas.
Paso 2: Extiende 100g de ricotta generosamente sobre cada tostada.
Paso 3: Lava 3 higos maduros. Córtalos en cuartos o láminas gruesas.
Paso 4: Coloca los higos sobre la ricotta.
Paso 5: Vierte un hilo de miel sobre el conjunto. Añade 3-4 nueces troceadas groseramente.
Consejo: Los higos solo tienen temporada en verano y otoño. Fuera de temporada, sustitúyelos por peras en láminas o uvas peladas: el resultado es igual de elegante.$ins$ WHERE id = '5e2df302-bfab-4098-a14e-374c13eca9b3';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan de centeno hasta que estén crujientes.
Paso 2: Lava unos tomates cherry y córtalos por la mitad.
Paso 3: Escurre bien 6 anchoas de lata.
Paso 4: Coloca las anchoas sobre el pan de centeno tostado.
Paso 5: Añade los tomates cherry alrededor. Esparce alcaparras escurridas.
Paso 6: Riega con un hilo de AOVE. Sirve inmediatamente.
Consejo: El pan de centeno es más denso y ácido que el trigo: aguanta bien el peso de las anchoas y la humedad de los tomates sin ablandarse.$ins$ WHERE id = '94404da7-0488-4adf-ac45-cf1877f4978a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan integral en la tostadora hasta que estén crujientes.
Paso 2: Extiende 50g de queso crema sobre cada tostada mientras aún están calientes.
Paso 3: Coloca 80g de salmón ahumado encima del queso crema.
Paso 4: Corta el pepino en rodajas muy finas y colócalas sobre el salmón.
Paso 5: Añade unas alcaparras si tienes. Espolvorea eneldo fresco o seco.
Consejo: El queso crema light tiene un 30% menos de calorías que el normal y la textura es prácticamente idéntica. Una sustitución sencilla para reducir calorías sin sacrificar sabor.$ins$ WHERE id = '390ad059-2b3c-412b-8c07-bf47e90cb99a';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan negro (pumpernickel o centeno oscuro).
Paso 2: Extiende queso crema light generosamente sobre cada rebanada.
Paso 3: Coloca 100g de salmón ahumado en lonchas encima.
Paso 4: Espolvorea eneldo fresco picado o seco.
Paso 5: Añade unas alcaparras y unas rodajas de pepino muy finas si tienes.
Consejo: El pan negro escandinavo tiene mucha más fibra y un índice glucémico más bajo que el pan de trigo normal. Es la base ideal para un desayuno que sacia durante horas.$ins$ WHERE id = '707221d0-ff0d-4ac5-9329-7dde89256399';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan integral.
Paso 2: Cuece 2 huevos a tu gusto: fritos (3 min), revueltos (2-3 min a fuego bajo) o pochados (3 min en agua con vinagre).
Paso 3: Pela 1 aguacate maduro, aplasta la pulpa con tenedor, añade sal, pimienta y zumo de limón.
Paso 4: Extiende el aguacate sobre las tostadas.
Paso 5: Coloca los huevos encima del aguacate.
Paso 6: Sazona con sal en escamas, pimienta recién molida y unas gotas de limón extra.
Consejo: La yema líquida del huevo frito mezclada con el aguacate crea una salsa natural que penetra en el pan. Por eso esta combinación es tan adictiva: tres texturas en un bocado.$ins$ WHERE id = '679ddfbe-dddc-449b-9de1-c9bdaeb5cf26';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan integral.
Paso 2: Extiende 1 cda colmada de mantequilla de cacahuete natural sobre cada tostada (2 cdas en total).
Paso 3: Pela 1 plátano maduro y córtalo en rodajas de 5mm.
Paso 4: Coloca las rodajas de plátano encima de la mantequilla de cacahuete.
Paso 5: Si quieres, añade un chorrito de miel encima del plátano.
Consejo: La mantequilla de cacahuete natural (solo cacahuetes y sal) es muy diferente a la industrial (con azúcar y aceites de palma). Lee siempre el etiquetado: debe tener 2 ingredientes máximo.$ins$ WHERE id = '9542c525-e618-4ba8-8bfc-ca449fe91eee';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 2 rebanadas de pan integral en la tostadora.
Paso 2: Extiende 100g de queso fresco en crema sobre cada tostada mientras aún están calientes.
Paso 3: Corta 2 tomates maduros en rodajas de 8mm.
Paso 4: Coloca las rodajas de tomate sobre el queso fresco.
Paso 5: Espolvorea orégano seco y un poquito de sal marina. Riega con 1 cdta de AOVE.
Consejo: Salar el tomate 5 minutos antes de colocarlo hace que suelte un jugo muy sabroso que impregna el queso. Un pequeño truco que multiplica el sabor.$ins$ WHERE id = 'a07b7716-9406-4c10-955e-88a39568b5b2';

UPDATE recetas SET instrucciones = $ins$Paso 1: Bate en un bol plano y amplio: 2 huevos, 100ml de leche, 1 cdta de vainilla y 1 cdta de canela.
Paso 2: Corta 2 rebanadas de pan del día anterior (mejor si está ligeramente seco: absorbe mejor el huevo).
Paso 3: Sumerge cada rebanada en la mezcla de huevo 30 segundos por cada lado.
Paso 4: Calienta sartén antiadherente con 1 cdta de aceite o mantequilla a fuego medio.
Paso 5: Cocina las rebanadas 2-3 minutos por lado hasta que estén bien doradas.
Paso 6: Sirve con fresas laminadas encima y un hilo de miel o sirope de arce.
Consejo: El pan del día anterior es el secreto de las torrijas perfectas: el pan fresco se empapa demasiado rápido y se rompe. El pan seco absorbe el huevo de forma uniforme.$ins$ WHERE id = '243c564a-6768-404c-9af1-5928d052c9d9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pica pimiento y champiñones en dados pequeños. Calienta 1 cdta de AOVE en sartén y sofríe 4 minutos.
Paso 2: Bate 2 huevos con sal y pimienta. Añade 30g de queso rallado.
Paso 3: Vierte los huevos sobre las verduras sofritas. Remueve con espátula haciendo movimientos de pliegue 2-3 minutos a fuego medio-bajo.
Paso 4: Retira del fuego con el huevo aún cremoso.
Paso 5: Calienta 1 tortilla integral en sartén seca 30 segundos por lado.
Paso 6: Coloca el revuelto sobre la tortilla. Dobla o enrolla. Sirve inmediatamente.
Consejo: El wrap de desayuno se puede preparar la noche anterior sin el huevo: las verduras sofritas en la nevera, y por la mañana solo tardas 3 minutos en acabar.$ins$ WHERE id = '17770efa-2de6-4745-8ada-c3b3a9a36b81';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca 200g de yogur griego 0% de la nevera.
Paso 2: Lava y lamina 100g de fresas frescas.
Paso 3: Coloca el yogur en un bol.
Paso 4: Extiende 40g de granola sobre el yogur.
Paso 5: Coloca las fresas laminadas encima de la granola.
Paso 6: Añade 1 cdta de miel en hilo. Sirve inmediatamente.
Consejo: El yogur griego 0% tiene prácticamente la misma proteína que el yogur griego entero (10g por 100g) con la mitad de grasa. La textura también es muy similar.$ins$ WHERE id = 'b38b8b27-9ee8-4447-88cd-78ddfbff5e2e';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 160°C.
Paso 2: Extiende 30g de almendras crudas en una bandeja con papel de horno en una sola capa.
Paso 3: Hornea 10-12 minutos hasta que estén doradas y aromáticas, sacudiendo la bandeja a mitad de tiempo.
Paso 4: Saca del horno y espolvorea sal marina en escamas inmediatamente mientras aún están calientes.
Paso 5: Deja enfriar completamente antes de comer: al enfriarse quedan crujientes.
Consejo: Las almendras tostadas en casa son muy superiores a las de bolsa: sin aceite de palma ni conservantes. Prepara 200g de una vez y guarda en tarro hermético 2 semanas.$ins$ WHERE id = '923b44b8-9e85-4d3f-95a0-a1534e948292';

UPDATE recetas SET instrucciones = $ins$Paso 1: En un bol mezcla 100g de proteína en polvo de sabor neutro o chocolate con 50g de copos de avena.
Paso 2: Añade 2 cdas de miel y 1 cda de mantequilla de cacahuete natural. Mezcla bien.
Paso 3: Si la masa está demasiado seca, añade 1-2 cdas de agua o leche de a cucharadas. Si está demasiado pegajosa, añade más avena.
Paso 4: Extiende la masa en molde rectangular forrado con papel de horno, aplastando bien con la mano para que quede uniforme de 1-1,5 cm de grosor.
Paso 5: Refrigera 30 minutos hasta que esté firme. Corta en barritas del tamaño deseado.
Consejo: Las barritas caseras se guardan en nevera hasta 5 días o en el congelador hasta 1 mes. Congélalas individualmente envueltas en papel para llevarlas al gym de forma práctica.$ins$ WHERE id = 'b0e1b7fd-edd3-4dd8-a0bc-6ddd541ee91b';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon en la batidora 1 scoop de proteína de vainilla (unos 30g) y 250ml de leche de avena bien fría.
Paso 2: Añade 4-5 cubitos de hielo.
Paso 3: Tritura a máxima potencia 20-30 segundos hasta que quede completamente liso y espumoso.
Paso 4: Sirve inmediatamente en vaso alto.
Consejo: La leche de avena aporta sabor más suave y ligeramente dulce que la de vaca, lo que reduce la necesidad de añadir edulcorantes adicionales al batido.$ins$ WHERE id = 'c8050096-0b01-42fc-bcb9-a1dfd78f5e90';

UPDATE recetas SET instrucciones = $ins$Paso 1: Escurre bien 100g de atún al natural con un tenedor presionando contra el colador para eliminar todo el líquido.
Paso 2: Pela un cuarto de aguacate y córtalo en trozos pequeños. Rocía con unas gotas de limón para evitar que se oxide.
Paso 3: Mezcla en un bol el atún escurrido con el aguacate. Aplasta ligeramente el aguacate con el tenedor.
Paso 4: Sazona con sal, pimienta y unas gotas más de limón.
Paso 5: Sirve en tostaditas de arroz o maíz hinchado a modo de bocadito.
Consejo: Las tostaditas de arroz tienen muy pocas calorías pero son muy crujientes. Prepara el relleno justo antes de comer para que no humedezcan y se ablanden.$ins$ WHERE id = '679f9fe5-d605-4273-aa2a-30bbe971f95d';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava bien 200g de frutas de temporada variadas (fresas, uvas, kiwi, naranja, manzana).
Paso 2: Pela y corta las que lo necesiten en trozos del tamaño de un bocado.
Paso 3: Coloca todas las frutas en un bol amplio.
Paso 4: Añade unas hojas de menta fresca lavadas encima.
Paso 5: Sirve inmediatamente. Si lo preparas con antelación, añade un chorrito de zumo de naranja para que no se oxide la manzana y el kiwi.
Consejo: Variar las frutas cada día asegura una amplia gama de vitaminas y antioxidantes. La menta fresca no es solo decoración: estimula la digestión y refresca el conjunto.$ins$ WHERE id = '813fe1cc-4c2d-4081-9295-95cc6f074a21';

UPDATE recetas SET instrucciones = $ins$Paso 1: Precalienta el horno a 200°C. Pela 200g de boniato y córtalo en láminas muy finas de 2-3mm (usa mandolina si tienes para uniformidad).
Paso 2: Coloca las láminas en un bol. Añade 1 cda de AOVE, sal, 1 cdta de pimentón dulce y ajo en polvo al gusto. Mezcla bien.
Paso 3: Extiende las láminas en una sola capa en bandeja con papel de horno. No superpongas.
Paso 4: Hornea 15 minutos. Da la vuelta a cada chip con pinzas.
Paso 5: Hornea 10-12 minutos más hasta que estén crujientes y dorados en los bordes.
Paso 6: Deja enfriar 5 minutos: terminan de crujir al enfriarse.
Consejo: Los chips de boniato son delicados. Si los amontonas en la bandeja, se cuecen al vapor en lugar de tostarse. Mejor usar dos bandejas que sobrecargar una sola.$ins$ WHERE id = '056fbbab-91b8-4f85-b569-d78173b53852';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca de la nevera el chocolate negro (guarda el chocolate en nevera para que no se blanquee y se conserve mejor).
Paso 2: Rompe 30g de chocolate negro 85% en 2-3 trozos.
Paso 3: Pon 10g de almendras (6-8 unidades) en un bol o plato pequeño.
Paso 4: Come el chocolate y las almendras juntos en cada bocado para equilibrar el amargor del cacao con la grasa de la almendra.
Consejo: El chocolate 85% tiene muy poco azúcar y mucha grasa saludable. Comerlo lentamente, dejándolo fundir en la boca, potencia la sensación de saciedad con mucha menos cantidad.$ins$ WHERE id = '6233fef5-f216-433d-b858-27c15f1a89e9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Si las gambas son crudas, cuécelas 2 minutos en agua hirviendo con sal. Enfría en agua con hielo y escurre. Si son congeladas cocidas, descongela bajo agua fría.
Paso 2: Prepara la salsa rosa: mezcla 3 cdas de mayonesa, 1 cda de kétchup, 1 cdta de zumo de limón y 1 cdta de brandy o coñac (opcional).
Paso 3: Coloca unas hojas de lechuga cortada en el fondo de una copa o bol.
Paso 4: Coloca 150g de gambas peladas encima de la lechuga.
Paso 5: Vierte la salsa rosa por encima. Espolvorea paprika y añade 1 rodaja de limón para decorar.
Consejo: La salsa rosa artesanal es mucho mejor que la de bote. El toque de brandy no se siente como alcohol sino como un matiz cálido que equilibra la mayonesa. Es el secreto.$ins$ WHERE id = 'ad3cf79e-d0ea-46dc-9d59-8111ebdf87ea';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 6 dátiles medjool. Ábrelos por la mitad con los dedos y retira el hueso.
Paso 2: Saca el queso crema de la nevera 5 minutos antes para que se ablande y sea fácil de trabajar.
Paso 3: Con una cucharilla o manga pastelera rellena cada mitad de dátil con queso crema.
Paso 4: Coloca media nuez encima de cada dátil relleno, presionando ligeramente.
Paso 5: Sirve en una pequeña bandeja. Se pueden refrigerar 24 horas antes de comer.
Consejo: Los dátiles medjool son los más carnosos y dulces. Si solo encuentras dátiles secos normales, remójalos 10 minutos en agua tibia para que se ablanden antes de rellenar.$ins$ WHERE id = 'a002d9e3-162e-4e90-a0d1-30d29ebfdfd4';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lleva agua a ebullición en una olla con sal.
Paso 2: Añade 150g de edamame con vaina (o en grano sin vaina). Cuece 3-4 minutos.
Paso 3: Escurre y transfiere a un bol.
Paso 4: Espolvorea sal marina generosamente mientras aún están calientes.
Paso 5: Si tienes, añade unas gotas de aceite de sésamo para potenciar el sabor asiático.
Consejo: El edamame con vaina se come apretando la vaina con los dientes para que los granos salten a la boca: es más divertido y los sabores de la sal en la vaina se mezclan en cada bocado.$ins$ WHERE id = 'fe1539c0-d1d4-4749-8687-f5ae45216429';

UPDATE recetas SET instrucciones = $ins$Paso 1: Calienta 400ml de zumo natural (naranja, manzana o una mezcla) en un cazo a fuego medio hasta que esté caliente pero sin hervir.
Paso 2: Disuelve 2 sobres de gelatina sin sabor (10-12g) en 100ml de zumo frío, removiendo bien.
Paso 3: Mezcla la gelatina disuelta con el zumo caliente. Remueve hasta que se integre completamente.
Paso 4: Vierte en moldes individuales. Añade frutas frescas en trozos (fresas, kiwi, uvas) dentro.
Paso 5: Refrigera mínimo 3 horas hasta que cuaje completamente.
Paso 6: Para desmoldar, sumerge el molde 5 segundos en agua caliente y voltea sobre el plato.
Consejo: La gelatina casera sin azúcar añadido tiene casi 0 calorías y aporta colágeno. Es el snack perfecto para antes de dormir: saciante, digestivo y sin impacto en la grasa.$ins$ WHERE id = 'c5f0668f-f067-413b-9116-9dcc3b86f904';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 1 huevo grande en un cazo pequeño. Cúbrelo con agua fría.
Paso 2: Lleva a ebullición a fuego fuerte.
Paso 3: En cuanto hierva, baja a fuego medio y cuece exactamente 10 minutos para yema bien cuajada o 7 minutos para yema cremosa.
Paso 4: Enfría bajo agua fría 2 minutos. Pela con cuidado.
Paso 5: Corta por la mitad. Espolvorea sal y pimienta negra recién molida.
Consejo: El huevo duro aguanta 5 días en nevera con cáscara y 2 días pelado. Prepara 4-5 de una vez el domingo: tienes snack proteico listo para toda la semana.$ins$ WHERE id = '1640b576-4a6c-48ab-8a6c-c20a7f19f8be';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 1 manzana y córtala en gajos finos, retirando el corazón. No es necesario pelarla.
Paso 2: Coloca los gajos de manzana en un bol o plato.
Paso 3: Pon 2 cdas de mantequilla de cacahuete natural en un pequeño cuenco al lado.
Paso 4: Come mojando cada gajo de manzana en la mantequilla de cacahuete.
Consejo: La combinación de la fibra y el azúcar natural de la manzana con la grasa y proteína de la mantequilla de cacahuete es perfecta para controlar el hambre 2-3 horas.$ins$ WHERE id = 'ae6b4ad8-1eb2-4fd1-b824-9245e6820a87';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pesa 10g de almendras, 10g de nueces, 10g de avellanas y 5g de piñones.
Paso 2: Mézclalos todos en un bol o recipiente pequeño.
Paso 3: Sirve directamente como snack a temperatura ambiente.
Consejo: Los frutos secos sin sal son superiores a los salados para el control del sodio. La variedad en cada puñado garantiza diferentes perfiles de grasas y micronutrientes. Pésalos: 35g parecen poco pero aportan 200 kcal.$ins$ WHERE id = 'e0cfffef-5b10-4f5d-8424-6ec9cdb65c24';

UPDATE recetas SET instrucciones = $ins$Paso 1: Lava 1 pepino y córtalo en bastones de 7-8 cm y 1 cm de grosor.
Paso 2: Coloca los bastones de pepino en un vaso o bol.
Paso 3: Pon 80g de humus en un cuenco pequeño al lado.
Paso 4: Come mojando los bastones de pepino en el humus.
Consejo: El pepino tiene un 96% de agua, lo que lo convierte en el snack más hidratante que existe. Combinado con el humus (rico en proteína vegetal) forman un snack completo y saciante.$ins$ WHERE id = 'bc94cc1f-bd76-4256-a03a-684589365bf9';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 30g de maíz palomitero en una olla con tapa con 1 cdta de aceite de coco.
Paso 2: Calienta a fuego medio-alto hasta que empiece a oírse el primer pop.
Paso 3: Tapa y agita la olla continuamente durante 2-3 minutos hasta que los pops se espacien a 2-3 segundos.
Paso 4: Retira del fuego. Espera 30 segundos antes de abrir la tapa.
Paso 5: Vierte en bol. Espolvorea cúrcuma, pimienta negra y sal mientras aún están calientes. Mezcla bien.
Consejo: Las palomitas caseras tienen 1/3 de las calorías de las de cine. La cúrcuma y la pimienta negra no solo dan sabor: activan la absorción de la curcumina, potente antiinflamatorio.$ins$ WHERE id = '5a5d0a7f-a7ef-48ab-974c-2ffde27d0b27';

UPDATE recetas SET instrucciones = $ins$Paso 1: Corta 100g de queso fresco en dados o láminas de 1 cm.
Paso 2: Coloca el queso en un plato o bol pequeño.
Paso 3: Espolvorea orégano seco generosamente por encima.
Paso 4: Añade una pizca de sal marina.
Paso 5: Riega con un hilo de AOVE de calidad extra virgen.
Paso 6: Añade unos tomates cherry partidos por la mitad alrededor.
Consejo: El queso fresco tiene la mitad de calorías que el queso curado con el mismo contenido proteico. Es el sustituto perfecto del feta cuando quieres controlar el sodio.$ins$ WHERE id = '3677448f-0fb4-4ae4-8efa-8929586801ca';

UPDATE recetas SET instrucciones = $ins$Paso 1: Saca 150g de requesón de la nevera.
Paso 2: Lava 2 higos frescos y córtalos en cuartos o en láminas.
Paso 3: Coloca el requesón en un bol.
Paso 4: Coloca los higos encima del requesón.
Paso 5: Vierte 1 cdta de miel sobre el conjunto. Añade unas nueces troceadas groseramente.
Consejo: El requesón es la proteína láctea más barata y versátil: se usa igual que el queso crema, el cottage o incluso el yogur pero con más proteína y menos grasa.$ins$ WHERE id = 'ee1c75f4-782e-4ad4-bd1b-bf0aac891251';

UPDATE recetas SET instrucciones = $ins$Paso 1: Extiende 3 lonchas de jamón york sobre una tabla.
Paso 2: Corta 30g de queso manchego en bastones de 5 cm.
Paso 3: Corta el pepino en bastones del mismo tamaño.
Paso 4: Coloca 1 bastón de queso y 1 de pepino en el extremo de cada loncha de jamón.
Paso 5: Enrolla el jamón sobre el queso y el pepino formando un rollito compacto.
Consejo: Este snack se prepara en 2 minutos y aporta proteína completa (jamón), calcio (queso) y agua (pepino). Es más nutritivo que cualquier barrita energética de bote.$ins$ WHERE id = '981bc3c2-951c-46fb-a4de-8b9489611b50';

UPDATE recetas SET instrucciones = $ins$Paso 1: Extiende 4 lonchas de pavo cocido sobre una tabla.
Paso 2: Pela la mitad de un aguacate y córtalo en tiras finas.
Paso 3: Riega el aguacate con unas gotas de zumo de limón y sazona con sal y pimienta.
Paso 4: Coloca unas tiras de aguacate en el extremo de cada loncha de pavo.
Paso 5: Enrolla el pavo sobre el aguacate formando rollitos compactos. Asegura con palillo si es necesario.
Consejo: El aguacate se oxida en minutos al contacto con el aire. Prepara estos rollitos justo antes de comer o rocía bien con limón y cúbrelos con film hasta que los consumas.$ins$ WHERE id = 'c20075a2-9921-48d9-8171-5b0d2172bb12';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 1 plátano maduro y trocéalo.
Paso 2: Pon en la batidora: el plátano, 1 cda de mantequilla de cacahuete natural y 200ml de leche.
Paso 3: Añade una pizca de canela.
Paso 4: Tritura a máxima potencia 30 segundos hasta que quede completamente liso.
Paso 5: Sirve inmediatamente en vaso.
Consejo: Este smoothie duplica la potencia con plátano congelado: más frío, más espeso y más cremoso. Congela siempre los plátanos que empiezan a madurar en exceso.$ins$ WHERE id = 'ba9fb14d-b0d1-453a-9180-6eb1b1afafcf';

UPDATE recetas SET instrucciones = $ins$Paso 1: Tuesta 1 rebanada de pan de centeno hasta que esté bien crujiente.
Paso 2: Pela un cuarto de aguacate maduro y aplasta la pulpa con tenedor.
Paso 3: Añade sal, pimienta y unas gotas de zumo de limón al aguacate aplastado. Mezcla bien.
Paso 4: Extiende el aguacate sobre la tostada de centeno.
Paso 5: Espolvorea semillas variadas (girasol, calabaza, sésamo) por encima.
Consejo: El pan de centeno tiene más fibra y menos índice glucémico que el pan de trigo. La combinación con aguacate crea un snack saciante que aguanta 2-3 horas sin hambre.$ins$ WHERE id = '26ee3a7b-13fa-4a28-a62d-b19b980f5832';

UPDATE recetas SET instrucciones = $ins$Paso 1: Coloca 3 tostadas de arroz en un plato.
Paso 2: Extiende mostaza (dijon, antigua o normal) sobre cada tostada de arroz.
Paso 3: Coloca 1-2 lonchas de pavo cocido dobladas encima de cada tostada.
Paso 4: Sirve inmediatamente.
Consejo: Las tostadas de arroz tienen solo 25 kcal por pieza y son crujientes durante 30 segundos antes de humedecerse con el relleno. Cómelas siempre recién preparadas.$ins$ WHERE id = '43f5ad4e-56ac-4eee-92db-db9913ceb474';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pon 150g de yogur natural sin azúcar (o yogur griego si prefieres más cremoso) en un bol.
Paso 2: Trocea groseramente 20g de nueces con las manos o con cuchillo.
Paso 3: Espolvorea las nueces sobre el yogur.
Paso 4: Añade una pizca generosa de canela molida.
Paso 5: Si quieres dulzor sin azúcar, añade unas gotas de stevia líquida o 1 cdta de miel.
Consejo: La canela tiene propiedades para regular los niveles de azúcar en sangre. Añadirla al yogur con proteína es especialmente útil como snack post-entrenamiento para optimizar la recuperación.$ins$ WHERE id = 'f6e94722-3748-4aa7-af59-67de5695eaad';

UPDATE recetas SET instrucciones = $ins$Paso 1: Pela 2 zanahorias y córtalas en bastones de 8 cm y 1 cm de grosor.
Paso 2: Lava 2 ramas de apio y córtalas en trozos del mismo tamaño.
Paso 3: Coloca los bastones de zanahoria y apio en un vaso o bol de forma vertical.
Paso 4: Pon 60g de queso crema light en un cuenco pequeño al lado.
Paso 5: Come mojando las verduras en el queso crema.
Consejo: La zanahoria y el apio tienen muy pocas calorías y mucha fibra. El queso crema light como dip aporta proteína y calcio sin apenas grasas saturadas. Un snack completo en menos de 3 minutos.$ins$ WHERE id = 'd4720ea5-759d-4b2c-b501-de683cfc349c';

